        private void _SynapseCoreData()
        {
            Logger.InfoFormat("Connection statred");
            if (connectionFactory == null)
            {
                connectionFactory = new ConnectionFactory(BROKER, CLIENT_ID);
                Logger.InfoFormat("connection factory - BROKER :: {0}", BROKER);
                if (connection == null)
                {
                    connection = connectionFactory.CreateConnection();
                }
            }

            try
            {
                if (!connection.IsStarted)
                    connection.Start();
                session = connection.CreateSession();
                Logger.InfoFormat("connection factory start - BROKER :: {0}", BROKER);
            }
            catch (Exception ex)
            {
                var exp = ex;
                Logger.Info(exp);
                Logger.InfoFormat("connection factory exception - BROKER :: {0}", BROKER);
            }
        }

