        //Dashboard AnalyticsGraph
        public async Task<DashBoardAnalyticsResponse> GetDashBoardAnalyticsAsync(DashBoardAnalyticsRequest request)
        {
            Logger.Info("GetDashBoardAnalyticsGraph - start : " + DateTime.Now);
            var response = new DashBoardAnalyticsResponse
            {
                AnalyticsGraph = new List<AnalyticsGraph>(),
            };
            try
            {
                using (var dbconsumer = new CoreDBConsumer())
                {
                    var dAnalyticsResult =
                        await
                        dbconsumer.DbConsumerForMultiItems<AnalyticsGraph>(request.Days == 1 ? "VM_DashBoard_hour_ANALYTICS" : "VM_DashBoard_day_ANALYTICS",
                                SqlEventTypes.Select, new Dictionary<string, object> { { "@Days", request.Days }, { "@UserId", request.UserId } }, false,
                                DBs.ReportsEngine);
                    if (dAnalyticsResult != null && dAnalyticsResult.Any())
                    {
                        response.AnalyticsGraph = dAnalyticsResult;
                    }
                    return response;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal Error throuing GetDashBoardAnalyticsGraph :: {0}", ex);
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            Logger.Info("GetDashBoardAnalyticsGraph - Exec Completed : " + DateTime.Now);
            return new DashBoardAnalyticsResponse();
        }

        //Dashboard SMSMO Graph
        public async Task<SMSMOResponse> GetSMSMOAnalyticsAsync(SMSMOAnalyticsRequest request)
        {
            Logger.Info("GetSMSMOAnalyticsAsync - start : " + DateTime.Now);
            var response = new SMSMOResponse
            {
                SMSMOAnalyticsResponse = new List<SMSMOAnalyticsResponse>(),
                SMSMOMinuteResponse = new List<SMSMOMinuteResponse>()
            };
            try
            {
                using (var dbconsumer = new CoreDBConsumer())
                {
                    var smsMoResult =
                        await
                        dbconsumer.DbConsumerForMultiItems<DataTable>("VM_DashBoard_day_ANALYTICS_MO",
                                SqlEventTypes.Select, new Dictionary<string, object> {
                                { "@Days", request.Days },
                                { "@UserId", request.UserId },
                                { "@Shortcode", request.Shortcode}
                                }, false, DBs.ReportsEngine);
                    if (smsMoResult != null && smsMoResult.Any())
                    {
                        response.SMSMOAnalyticsResponse = smsMoResult[0].ToList<SMSMOAnalyticsResponse>();
                        response.SMSMOMinuteResponse = smsMoResult[1].ToList<SMSMOMinuteResponse>();
                    }
                    return response;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal Error throuing GetSMSMOAnalyticsAsync :: {0}", ex);
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            Logger.Info("GetSMSMOAnalyticsAsync - Exec Completed : " + DateTime.Now);
            return new SMSMOResponse();
        }

        //Dashboard Modules
        public async Task<DashBoardAnalyticsResponse> GetDashBoardModulesAsync(DashBoardAnalyticsRequest request)
        {
            Logger.Info("GetDashBoardModules - start : " + DateTime.Now);
            var response = new DashBoardAnalyticsResponse
            {
                Modules = new Modules(),
            };
            try
            {
                using (var dbconsumer = new CoreDBConsumer())
                {
                    var dModules = await dbconsumer.DbConsumerForMultiItems<ModulesCollection>("VM_DashBoard_Module", SqlEventTypes.Select,
                        new Dictionary<string, object> { { "@Days", request.Day }, { "@UserId", request.UserId } }, false, DBs.ReportsEngine);
                    if (dModules != null && dModules.Any())
                    {
                        var module = new Modules();
                        var mProps = module.GetType().GetProperties();
                        foreach (var prop in mProps)
                        {
                            var mprop = (from n in dModules
                                         where n.Module.Equals(prop.Name, StringComparison.OrdinalIgnoreCase)
                                         select n).FirstOrDefault();
                            if (mprop != null)
                            {
                                prop.SetValue(module, Convert.ChangeType(mprop.Count, prop.PropertyType), null);
                            }
                        }
                        response.Modules = module;
                    }
                    return response;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal Error throuing GetDashBoardModules :: {0}", ex);
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            Logger.Info("GetDashBoardModules - Exec Completed : " + DateTime.Now);
            return new DashBoardAnalyticsResponse();
        }

        //Dashboard SucessRatio
        public async Task<DashBoardAnalyticsResponse> GetDashBoardSucessRatioAsync(DashBoardAnalyticsRequest request)
        {
            Logger.Info("GetDashBoardSucessRatio - start : " + DateTime.Now);
            var response = new DashBoardAnalyticsResponse
            {
                SucessRatio = new SuccessRatio(),
            };
            try
            {
                using (var dbconsumer = new CoreDBConsumer())
                {

                    var dSuccessRatio =
                        await
                            dbconsumer.DbConsumerForMultiItems<SucessRatioCollection>("VM_DashBoard_SucessRatio", SqlEventTypes.Select,
                                new Dictionary<string, object> { { "@Days", request.Days }, { "@UserId", request.UserId } }, false, DBs.ReportsEngine);
                    if (dSuccessRatio != null && dSuccessRatio.Any())
                    {
                        var ratio = new SuccessRatio();

                        var TProps = ratio.GetType().GetProperties();
                        foreach (var prop in TProps)
                        {
                            var sprop = (from n in dSuccessRatio
                                         where n.DlrStatus.Equals(prop.Name, StringComparison.OrdinalIgnoreCase)
                                         select n).FirstOrDefault();
                            if (sprop != null)
                            {
                                prop.SetValue(ratio, Convert.ChangeType(sprop.Count, prop.PropertyType), null);
                            }
                        }
                        response.SucessRatio = ratio;
                    }
                    return response;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal Error throuing GetDashBoardSucessRatio :: {0}", ex);
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            Logger.Info("GetDashBoardSucessRatio - Exec Completed : " + DateTime.Now);
            return new DashBoardAnalyticsResponse();
        }

