        /// <summary>
        /// Method Name : CheckerUpdateQuickSMS
        /// Created By : 
        /// Created On :30th JAN 2017 
        /// Purpose : To Approve or Reject of selected Quick SMS
        /// Modified By : 
        /// Modified On :
        /// Details of Modification :  
        /// </summary>
        public async Task<int> CheckerUpdateQuickSMS(CheckerUpdateQSMSOnRequest request)
        {
            Logger.InfoFormat("CheckerUpdateQuickSMS :: start :: {0}", request.QSMSID);
            try
            {
                using (var _consumer = new CoreDBConsumer())
                {
                    if (request.ModuleType == 0)
                    {
                        var res =
                            await
                                _consumer.DbConsumer<ReUsableResponse>("ApproveOrRejectQuickSMS", SqlEventTypes.Select,
                                    new Dictionary<string, object>()
                                    {
                                        {"@ID", request.QSMSID},
                                        {"@Status", request.Status},
                                        {"@CurrentStatus", request.CurrentStatus},
                                        {"@Rejectreason", request.RejectReason},
                                        {"@UpdatedBy", request.UpdatedBy},
                                        {"@nReturn", DBNull.Value}
                                    });
                        return res.nReturn;
                    }
                    else
                    {
                        var res =
                            await
                                _consumer.DbConsumer<ReUsableResponse>("ApproveOrRejectCampaign", SqlEventTypes.Select,
                                    new Dictionary<string, object>()
                                    {
                                        {"@ID", request.QSMSID},
                                        {"@Status", request.Status},
                                        {"@CurrentStatus", request.CurrentStatus},
                                        {"@Rejectreason", request.RejectReason},
                                        {"@UpdatedBy", request.UpdatedBy},
                                        {"@nReturn", DBNull.Value}
                                    });

                        if (res.cstatus == 1)
                        {
                            //var QMsg = "action=stop&camp_id=" + request.QSMSID + "&camp_type=" + res.schduletype + "&dir_name=" + res.dirname + "&count=" + res.tcount;

                            var QMsg = "action=start&camp_id=" + request.QSMSID + "&camp_type=" + res.schduletype + "&dir_name=" + res.dirname + "&count=" + res.tcount;
                            var Qresult = new CampaignQLog().PushMessageToQ(QMsg);
                        }
                        return res.nReturn;
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("CheckerUpdateQuickSMS Fatal error thoughs :: Err0r :: {0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }

            return 0;
        }

