        public async Task<DndNonDndNumbers> DndNumberCheck(ReUsableRequest request)
        {
            Logger.InfoFormat("DndNumberCheck - start :: {0} :: time :: {1} ", request.MobileNo.TrimEnd(',').Split(',').Count(), DateTime.Now);
            //DataTable dt = new DataTable();
            var dndList = new DndNonDndNumbers();
            //var CampaignDndnumbers = new CampaignDndnumbers
            //{
            //    strDndNumbers = new List<string>(),
            //    //strNonDndNumbers = new List<strNonDndNumbers>()
            //};
            try
            {
                using (var dbConsumer = new CoreDBConsumer())
                {
                    XDocument xmlDoc = new XDocument();
                    XElement xElm = new XElement("DNDNUMBERS",
                                        from l in request.MobileNo.TrimEnd(',').Split(',')
                                        select new XElement("DNDNO", new XAttribute("MobileNo", l))
                                    );
                    xmlDoc.Add(xElm);

                    var resp = await dbConsumer.DbConsumerForMultiItems<DataTable>("CheckDNDxml", SqlEventTypes.Select,
                            new Dictionary<string, object>()
                        {
                            {"@xmlDNDNos", xElm.ToString()}
                            //{"@NRETVAL", DBNull.Value}
                        }, false, DBs.DND);


                    if (resp != null)
                    {
                        // List<strDndNumbers> dndList = new List<strDndNumbers>();
                        dndList.strDndNumbers = resp[0].ToList<strDndNumbers>();
                        dndList.strNonDndNumbers = resp[1].ToList<strNonDndNumbers>();
                        // dndList = resp[0].ToList<strDndNumbers>();

                        //dndList = (from DataRow dr in resp[0].Rows
                        //           select new strDndNumbers()
                        //               {
                        //                   DNDNumbers = dr[0].ToString()
                        //               }).ToList();

                        //List<Student> studentDetails = new List<Student>();
                        //studentDetails = ConvertDataTable<Student>(dt);  
                    }

                    // CampaignDndnumbers.strDndNumbers = resp[0].ToList<strDndNumbers>();
                    //CampaignDndnumbers.strNonDndNumbers = resp[1].ToList<strNonDndNumbers>();
                    //Logger.Info("DndNumberCheck - End : " + dndList.strDndNumbers.Count);
                    //Logger.Info("NonDndNumberCheck - End : " + dndList.strNonDndNumbers.Count);
                    Logger.InfoFormat("DndNumberCheck - end :: {0} :: time :: {1} ", request.MobileNo.TrimEnd(',').Split(',').Count(), DateTime.Now);
                    return dndList;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal Error thouging from DndNumberCheck :: {0} ", ex.StackTrace);
                ErrorSignal.FromCurrentContext().Raise(ex);
            }

            return dndList;
        }

        /// <summary>
        /// Method Name : InsertTestSMSCamp
        /// Created By : 
        /// Created On : 13/02/2017
        /// Purpose : Insert TestSMS details into stage table
        /// Modified By : 
        /// Modified On :
        /// Details of Modification :  
        /// </summary>  
        public async Task<string> InsertTestSMSCamp(InsertTestSMSOnRequest TRequest)
        {
            Logger.InfoFormat("InsertTestSMSCamp :: start :: {0}", TRequest.CustomerID);
            List<int> Response = new List<int>();
            //commented for to resolve warning the variable ReturnVal is assigned but its value is never used
            // string ReturnVal = "";
            try
            {

                var tCounts = TRequest.MobileNo.Split(',').Length;
                if (tCounts == 0)
                {
                    tCounts = 1;
                }
                var LangID = TRequest.LanguageId;
                if (LangID == 2)
                    LangID = 8;
                //else
                //{
                //    if (TRequest.Message.Contains('@') || TRequest.Message.Contains('{') || TRequest.Message.Contains('}'))
                //        LangID = 1;
                //    else
                //        LangID = 1;
                //}
                var randNo = 0;
                var fileName = string.Empty;
                var xmlContent = string.Empty;
                var xmlContent1 = string.Empty;
                var iscustomtf = TRequest.IsCustomTest == true ? "true" : "false";
                //var dndmobs;
                //var nondndmobs;
                var str = string.Empty;
                var str1 = string.Empty;
                var str2 = string.Empty;
                var str3 = string.Empty;
                //var mobs = TRequest.MobileNo.Split(',').Where(w => !string.IsNullOrWhiteSpace(w)).Select(s => s);

                var mobs = TRequest.MobileNo.Split(',').Where(w => !string.IsNullOrWhiteSpace(w)).Select(s => s).Distinct().ToList();

                //var Duplicates = mobs.Cast<DataRow>().GroupBy(p => p[mobColumnName]).Where(g => g.Count() > 1).SelectMany(ss => ss.Skip(1)).Select(s => s[mobColumnName].ToString()).ToList();
                //mobileColumn = (Duplicates.Any()) ? mobRows.Where(x => !string.IsNullOrWhiteSpace(x[mobColumnName].ToString())).Select(s => s[mobColumnName].ToString()).ToList() : dt.Rows.Cast<DataRow>().Where(x => !string.IsNullOrWhiteSpace(x[mobColumnName].ToString())).Select(s => s[mobColumnName].ToString()).ToList();

                //foreach (var item in mobs)
                //{
                //    str2 = str2 + ("91" + item) + ",";
                //}

                if (TRequest.IsCustomTest) //Custom Testsms
                {
                    if (!string.IsNullOrWhiteSpace(TRequest.Filepath)) //File is not null
                    {
                        randNo = 0;
                        fileName = DateTime.Now.ToString("ddMMyyyyhhmmss") + randNo;
                        DataTable dt = IEnumerableExtension.BuildCsvToTable(TRequest.Filepath, TRequest.SheetName);
                        //foreach (DataRow item in dt.Rows)
                        //{

                        //    if ((item["Mobileno"].ToString().Length) == 10)
                        //    {
                        //        item["Mobileno"] = "91" + item["Mobileno"];
                        //    }
                        //}
                        if (System.Configuration.ConfigurationManager.AppSettings["IndianSynapse"] == "true" && !Regex.IsMatch(TRequest.Sender, @"^[a-zA-Z]+$") ||
                        (System.Configuration.ConfigurationManager.AppSettings["IndianSynapse"] == "true" && Regex.IsMatch(TRequest.Sender, @"^[a-zA-Z]+$") && TRequest.CampaignType == "Promotional"))
                        {
                            xmlContent = "<root iscustome='" + iscustomtf + "' priority='5'>";
                            foreach (var item in mobs)
                            {
                                str = str + item.Substring(2, 10) + ",";
                            }

                            //var NoCheck = DndNumberCheck(TRequest.MobileNo);
                            Logger.Info("DndNumberCheck - start : " + str.TrimEnd(',').Split(',').Count());
                            var dndList = new List<strDndNumbers>();
                            using (var dbConsumer = new CoreDBConsumer())
                            {
                                XDocument xmlDoc = new XDocument();
                                XElement xElm = new XElement("DNDNUMBERS",
                                                    from l in str.TrimEnd(',').Split(',')
                                                    select new XElement("DNDNO", new XAttribute("MobileNo", l)
                                                    )
                                                );
                                xmlDoc.Add(xElm);

                                var resp = await dbConsumer.DbConsumerForMultiItems<DataTable>("CheckDNDxml", SqlEventTypes.Select,
                                        new Dictionary<string, object>()
                                    {
                                        {"@xmlDNDNos", xElm.ToString()}
                                    }, false, DBs.DND);

                                if (resp != null)
                                {
                                    dndList = resp[0].ToList<strDndNumbers>();
                                }
                                Logger.Info("DndNumberCheck - end : " + dndList.Count());
                            }

                            HashSet<string> noche = new HashSet<string>(dndList.Select(s => s.DNDNumbers));
                            List<string> nondnd = mobs.ToList();


                            str = "";
                            foreach (var item in noche)
                            {
                                str = str + ("91" + item) + ',';
                                nondnd.Remove(("91" + item));

                            }

                            mobs = nondnd.ToList();

                            //TRequest.MobileNo = string.Join(",", nondnd);

                            if (str.Split(',').Count() > 0 && str != "")
                            {
                                if (System.Configuration.ConfigurationManager.AppSettings["IndianSynapse"] == "true")
                                {
                                    foreach (string m in str.TrimEnd(',').Split(','))
                                    {
                                        var row = dt.Rows.Cast<DataRow>().FirstOrDefault(w => w[TRequest.MobileColumn].ToString().Equals(m.Substring(2, 10)));
                                        var message = string.Empty;//WebUtility.HtmlEncode(TRequest.msgtemptext);
                                        var messageTemplates = IEnumerableExtension.StringBetween(TRequest.msgtemptext, "<$", "$>");
                                        if (row != null)
                                        {
                                            message = TRequest.msgtemptext;
                                            foreach (var item in messageTemplates)
                                            {
                                                message = message.Replace("<$" + item + "$>", (row[item] != null && row[item].ToString() != "") ? row[item].ToString() : "");
                                            }
                                            var lid = LangID;
                                            var ccountlid = message.validateMessage(lid).Split(',');
                                            var ccount = ccountlid[0];
                                            lid = Convert.ToInt32(ccountlid[1]);
                                            LangID = lid;
                                            xmlContent += "<sendsms userid='" + TRequest.UserID + "' username='" + TRequest.UserName + "' campainid='" +
                                             randNo + "' sender='" + WebUtility.HtmlEncode(TRequest.Sender) +
                                             "' language='" + ((LangID == 2) ? 8 : IsHavingAttheRate(message)) + "' message='" +
                                            WebUtility.HtmlEncode(message).Replace("\n", "&#10;") +
                                            "' mobile='" + WebUtility.HtmlEncode(m) + "'></sendsms>";
                                        }
                                        else
                                        {
                                            message = message.Replace("<$" + TRequest.MobileColumn + "$>", m);
                                            foreach (var item in messageTemplates)
                                            {
                                                message = message.Replace("<$" + item + "$>", "");
                                            }
                                            int lid = LangID;
                                            var ccountlid = message.validateMessage(lid).Split(',');
                                            var ccount = ccountlid[0];
                                            lid = Convert.ToInt32(ccountlid[1]);
                                            LangID = lid;
                                            xmlContent += "<sendsms userid='" + TRequest.UserID + "' username='" + TRequest.UserName + "' campainid='" +
                                                        randNo + "' sender='" + WebUtility.HtmlEncode(TRequest.Sender) +
                                                        "' language='" + ((LangID == 2) ? 8 : IsHavingAttheRate(message)) + "' message='" +
                                                        WebUtility.HtmlEncode(message).Replace("\n", "&#10;") +
                                                        "' mobile='" + WebUtility.HtmlEncode(m) + "'></sendsms>";
                                        }
                                    }
                                }
                                else
                                {
                                    foreach (string m in str.TrimEnd(',').Split(','))
                                    {
                                        // var row = dt.Rows.Cast<DataRow>().FirstOrDefault(w => w[TRequest.MobileColumn].ToString().Equals(m));
                                        string searchExpression = TRequest.MobileColumn + "='" + m + "'";
                                        //mobColumnName + "='" + item + "'"

                                        var filterdt = dt.Rows.Cast<DataRow>().GroupBy(s => s[TRequest.MobileColumn]).Select(x => x.First()).CopyToDataTable();

                                        DataRow[] rows = filterdt.Select(searchExpression);
                                        var message = string.Empty;
                                        var messageTemplates = IEnumerableExtension.StringBetween(TRequest.msgtemptext, "<$", "$>");
                                        //var mob1 = string.Join(",", ele);
                                        message = TRequest.msgtemptext;
                                        if (rows.Count() > 0)
                                        {
                                            foreach (DataRow row in rows)
                                            {
                                                foreach (var item in messageTemplates)
                                                {
                                                    message = message.Replace("<$" + item + "$>", (row[item] != null && row[item].ToString() != "") ? row[item].ToString() : "");
                                                }
                                                int lid = LangID;
                                                var ccountlid = message.validateMessage(lid).Split(',');
                                                var ccount = ccountlid[0];
                                                lid = Convert.ToInt32(ccountlid[1]);
                                                LangID = lid;
                                                xmlContent += "<sendsms userid='" + TRequest.UserID + "' username='" + TRequest.UserName + "' campainid='" +
                                                         randNo + "' sender='" + WebUtility.HtmlEncode(TRequest.Sender) +
                                                         "' language='" + ((LangID == 2) ? 8 : IsHavingAttheRate(message)) + "' message='" +
                                                         WebUtility.HtmlEncode(message).Replace("\n", "&#10;") +
                                                         "' mobile='" + WebUtility.HtmlEncode(m) + "'></sendsms>";
                                            }
                                        }
                                        else
                                        {
                                            message = message.Replace("<$" + TRequest.MobileColumn + "$>", m);
                                            foreach (var item in messageTemplates)
                                            {
                                                message = message.Replace("<$" + item + "$>", "");
                                            }
                                            int lid = LangID;
                                            var ccountlid = message.validateMessage(lid).Split(',');
                                            var ccount = ccountlid[0];
                                            lid = Convert.ToInt32(ccountlid[1]);
                                            LangID = lid;
                                            xmlContent += "<sendsms userid='" + TRequest.UserID + "' username='" + TRequest.UserName + "' campainid='" +
                                                        randNo + "' sender='" + WebUtility.HtmlEncode(TRequest.Sender) +
                                                        "' language='" + ((LangID == 2) ? 8 : IsHavingAttheRate(message)) + "' message='" +
                                                        WebUtility.HtmlEncode(message).Replace("\n", "&#10;") +
                                                        "' mobile='" + WebUtility.HtmlEncode(m) + "'></sendsms>";
                                        }
                                    }
                                }
                                xmlContent += "</root>";
                                var fPath = Path.Combine((System.Configuration.ConfigurationManager.AppSettings["CampaintPath"] + "QuickSMS"), fileName);
                                if (!Directory.Exists(fPath))
                                {
                                    Directory.CreateDirectory(fPath);
                                }
                                if (!string.IsNullOrWhiteSpace(xmlContent))
                                    File.WriteAllText(Path.Combine(fPath, fileName + "_dnd.xml"), xmlContent);

                            }
                        }

                        if (mobs.Count() > 0)
                        {
