        public static int IsHavingAttheRate(string value)
        {
            return value.Contains('@') || value.Contains('}') || value.Contains('{') ? 1 : 1;

        }

        /// <summary>
        /// Method Name : SetCampaignEvents
        /// Created By : 
        /// Created On : 17/02/2017
        /// Purpose : 
        /// Modified By : 
        /// Modified On :
        /// Details of Modification :  
        /// </summary>  
        public async Task<int> SetCampaignEvents(SetCampEventsOnRequest request)
        {
            Logger.InfoFormat("SetCampaignEvents :: start :: {0}", request.CampID);
            try
            {
                using (var _consumer = new CoreDBConsumer())
                {
                    var response = await _consumer.DbConsumer<ReUsableResponse>("SetCampaignEvents", SqlEventTypes.Select,
                        new Dictionary<string, object> {
                    {"@CampID",request.CampID},
                    {"@StageIDs",request.StageIDs},
                    {"@Status",request.Status},
                    {"@CreatedBy",request.CreatedBy},
                    {"@CurrentStatus",request.CurrentStatus},
                    {"@NRETVAL",DBNull.Value},
                    {"@UserIp",request.UserIp}
                    });
                    //  var QMsg = "action=stop&camp_id=" + request.CampID + "&camp_type=0&dir_name=" + request. +;
                    //  var QMsg = "action=stop&camp_id=" + request.CampID + "&camp_type=0";
                    //  var QMsg = "action=stop&camp_id=" + request.CampID + "&camp_type=0&dir_name=" + request.dirname + "&count=" + request.tcount;
                    var QMsg = "action=stop&camp_id=" + request.CampID + "&camp_type=2&dir_name=" + response.dirname + "&count=" + response.tcount;
                    var Qresult = new CampaignQLog().PushMessageToQ(QMsg);

                    return response.NRETVAL;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal Error thouging from SetCampaignEvents :: {0} ", ex.StackTrace);
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return 0;
        }

