        public async Task<List<ShowGridQuickOnResponse>> ShowGridQuick(ShowGridQuickOnRequest request)
        {
            Logger.InfoFormat("ShowGridQuick :: start :: {0}", request.CreatedUserId);
            try
            {
                if (request.ModuleType != 4)
                {
                    if (request.ModuleType == 0)
                    {
                        request.ischecker = true;
                    }
                    if (request.ischecker == false)
                    {
                        using (var _consumer = new CoreDBConsumer())
                        {
                            var result = await
                                _consumer.DbConsumerForMultiItems<ShowGridQuickOnResponse>("GETCAMPAIGNS_Checker",
                                    SqlEventTypes.Select,
                                    new Dictionary<string, object>()
                            {
                                {"@nCMPId", request.QuickOrCampaignId},
                                {"@nAddedBy", request.CreatedUserId},
                                {"@nStatus", request.Status},
                                {"@strCampaign", request.SearchCampaign},
                                {"@strFrom", request.FromDate},
                                {"@strTo", request.ToDate},
                                {"@nModuleType", request.ModuleType},
                                {"@nReturn", 0},
                                {"@UserIp",request.UserIp}
                            });
                            var abc = result.OrderByDescending(x => x.CreatedOn);
                            return result;
                        }
                    }
                    using (var _consumer = new CoreDBConsumer())
                    {
                        var result = await
                            _consumer.DbConsumerForMultiItems<ShowGridQuickOnResponse>("GETCAMPAIGNSOrQuickSMSDetails",
                                SqlEventTypes.Select,
                                new Dictionary<string, object>()
                            {
                                {"@nCMPId", request.QuickOrCampaignId},
                                {"@nAddedBy", request.CreatedUserId},
                                {"@nStatus", request.Status},
