                                        DateTime.ParseExact(request.ValidFrom, "dd-MMM-yyyy",
                                            System.Globalization.CultureInfo.InvariantCulture)
                                    },
                                    {
                                        "@dtmValidTo",
                                        DateTime.ParseExact(request.ValidTo, "dd-MMM-yyyy",
                                            System.Globalization.CultureInfo.InvariantCulture)
                                    },
                                    {"@nuserid", request.UserID},
                                    {"@nCustid", request.CustomerID},
                                    {"@nlang", request.Language},
                                    {"@NRETVAL", 0}
                                });
                    }
                    else
                    {
                        return await
                            _consumer.DbConsumer<int>("VM_UPDATE_KEYWORDS", SqlEventTypes.Update,
                                new Dictionary<string, object>()
                                {
                                    {"@nId", request.KeyID},
                                    {"@strKeyName", request.KeyName},
                                    {"@strDesc", request.KeyDescription},
                                    {
                                        "@dtmValidFrom",
