        public async Task<int> InsertGroups(SaveGroupsOnRequests request)
        {
            Logger.InfoFormat("ShowGridGroup :: Started :: GroupName :: ", request.GroupName);
            try
            {
                using (var _consumer = new CoreDBConsumer())
                {
                    if (request.EventType == SqlEventTypes.Insert)
                    {
                        var result = await
                            _consumer.DbConsumer<ReUsableResponse>("SETGROUPS", SqlEventTypes.Select,
                                new Dictionary<string, object>()
                                {
                                    {"@STRNAME", request.GroupName},
                                    {"@STRDESC", request.Description},
                                    {"@NCREATEDBY", request.GroupActionBy},
                                    {"@CRNTSTATUS", request.CurrentStatus},
                                    {"@NRETVAL", 0},
                                    {"@UserIp",request.UserIp}
                                });
                        return result.NRETVAL;
                    }
                    if (request.EventType == SqlEventTypes.Update)
                    {
                        var result = await
                            _consumer.DbConsumer<ReUsableResponse>("UPDATEGROUPS", SqlEventTypes.Select,
                                new Dictionary<string, object>()
                                {
                                    {"@NID", request.GroupId},
                                    {"@STRNAME", request.GroupName},
                                    {"@STRDESC", request.Description},
                                    {"@NUPDATEDBY", request.GroupActionBy},
                                    {"@NRETVAL", 0},
                                    {"@UserIp",request.UserIp}
                                });
                        return result.NRETVAL;
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal Error while executing InsertGroups :: {0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return 0;
        }

