                                    {"@STRLNAME", request.LASTNAME},
                                    {"@STREMAIL", request.EMAIL},
                                    {"@STRMOBILE", request.MOBILE},
                                    {"@STRGROUPIDS", request.GROUPIDS},
                                    {"@NCREATEDBY", request.CREATEDBY},
                                    {"@Currentstatus", request.CURRENTSTATUS},

                                    {"@NRETVAL", DBNull.Value},
                                    {"@UserIp",request.UserIp}
                                });
                        return response.NRETVAL;
                    }
                    else
                    {
                        var response = await
                            _consumer.DbConsumer<ReUsableResponse>("UpdateContactUsers", SqlEventTypes.Select,
                                new Dictionary<string, object>()
                                {
                                    {"@NID", request.CONTACTID},
                                    {"@STRFNAME", request.FIRSTNAME},
                                    {"@STRLNAME", request.LASTNAME},
                                    {"@STREMAIL", request.EMAIL},
                                    {"@STRMOBILE", request.MOBILE},
                                    {"@STRGROUPIDS", request.GROUPIDS},
                                    {"@NUPDATEDBY", request.CREATEDBY},
                                    {"@CURRENTSTATUS", request.CURRENTSTATUS},
                                    {"@GroupUpdate", request.GroupUpdate },
                                    {"@NRETVAL", DBNull.Value},
                                    {"@UserIp",request.UserIp}
                                });
                        return response.NRETVAL;
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("InsertContacts :: Error :-{0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return 0;
        }

