        /// <summary>
        /// Method Name : ImportContacts
        /// Created By : 
        /// Created On : 19/09/2016
        /// Purpose : To insert Contacts into DB from Notepad or Excel file
        /// Modified By : 
        /// Modified On :
        /// Details of Modification :  
        /// </summary> 
        public async Task<int> ImportContacts(ImportContactsCSVOnRequest request)
        {
            Logger.InfoFormat("IMPORTCONTACTsTART :: Started");
            try
            {
                using (var _consumer = new CoreDBConsumer())
                {
                    var rresp = new List<int>();
                    foreach (var g in request.GROUPIDS.Split(','))
                    {
                        var xEle = new XElement("Contacts",
                            from Contact in request.ContactsList
                            select new XElement("Contact",
                                new XElement("STRFNAME", Contact.FirstName ?? ""),
                                new XElement("STRLNAME", Contact.LastName ?? ""),
                                new XElement("STREMAIL", Contact.Email ?? ""),
                                new XElement("STRMOBILE", Contact.MobileNo),
                                new XElement("STRGROUPIDS", g),
                                new XElement("NCREATEDBY", request.CREATEDBY),
                                new XElement("Currentstatus", request.CURRENTSTATUS)
                                ));
                        var resp = await _consumer.DbConsumer<ReUsableResponse>("SetContactUsersxml", SqlEventTypes.Select,
                            new Dictionary<string, object>()
                        {
                            {"@xmlContacts", xEle.ToString()},
                            {"@contactcnt", request.ContactsList.Count()},
                            {"@NRETVAL", DBNull.Value}
                        });

                        rresp.Add(resp.NRETVAL);

                    }

                    Logger.Info("IMPORTCONTACTeXECUTIONeND");
                    return rresp.Where(w => w == 7).Count() > 0 ? 7 : 2;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("ImportContacts :: Error :-{0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return 0;
        }

