                                    {"@Status", Request.Status},
                                    {"@Createdby", Request.CreatedBy},

                                    {"@requestedby", Request.requestedby},
                                    {"@UserIp",Request.UserIp}
                                });
                    Logger.InfoFormat("GetEmailToSMS :: End :: Fetched Id Count :: {0} ", Email.Count);
                    if (Email.Any())
                    {
                        Email.ForEach(x =>
                        {
                            //var splititems = x.Formats.Split(',');
                            x.Formats = (x.Formats != null
                                ? string.Join(",", (from n in strFormats
                                                    join si in x.Formats.Split(',') on n.Key.ToString() equals si
                                                    select n.Value))
                                : "0");
                        });
                    }

                    return Email;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("GetEmailToSMS :: {0} :: Error :: {1}", Request.ID, ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return null;
        }


