        public async Task<CustomerCreationResponse> CreateCustomerAsync(CustomerCreationRequest request)
        {
            var response = new CustomerCreationResponse();
            Logger.InfoFormat("CreateCustomerAsync :: started :: {0} :: {1}", request.Id, request.Name);
            try
            {
                using (var dbconsumer = new CoreDBConsumer())
                {
                    var result =
                        await
                            dbconsumer.DbConsumer<ReUsableResponse>("CreateCustomer", SqlEventTypes.Select,
                                buildCreateCustomerRequest(request));
                    if (result != null)
                    {
                        var ran = GenerateRandomNo();
                        // CreateToCustomerCount = request.CreateToCustomerCount+1,  code modified  on 10/03/2017
                        switch (result.ReturnValue)
                        {
                            case 1:
                                if (request.Id <= 0)
                                {
                                    request.Name = string.Join("", request.Name.Split(new string[] { " " }, StringSplitOptions.None).Where(w => !string.IsNullOrWhiteSpace(w)));
                                    var UserResponse = UpdateUserByUserId(new UpdateUserRequest
                                    {
                                        UserName = AppInternalEncKey.Encrypt(request.Name.Substring(0, 4) + ran, false),
                                        Password = AppInternalEncKey.Encrypt(request.Name.Substring(0, 4) + ran, false),
                                        Ldap = false,
                                        command = "Add",
                                        FirstName = request.Name + ran,
                                        LastName = request.Name + ran,
                                        Mail = request.Email,
                                        MobileNo = request.Mobile,
                                        RoleId = 2,
                                        divisionid = 1,
                                        CreateToCustomerCount = request.CreateToCustomerCount,
                                        CustomerId = result.IdentityCustomer,
                                        IsDefaultCustomer = true,
                                        Status = true,
                                        CurrentStatus = 1,
                                        Web = true,
                                        Createdby = request.CreatedBy,
                                        UserIp = request.UserIp
                                    });
                                    Logger.InfoFormat("CreateCustomerAsync :: End :: CreateCustomerAsync :: {0}", UserResponse.Id);
                                    if (UserResponse != null)
                                    {
                                        var ddsave = AddDetailDivision(result.IdentityCustomer, request.CreatedBy);
                                    }
                                }
                                if (request.CurrentStatus == 1)
                                {
                                    AdminNotificationCallOne("Route");
                                }

                                return new CustomerCreationResponse
                                {
                                    ConditionalResponse = true,
                                    ResultResponse = result.ReturnValue,
                                    Merssage =
                                        request.Id > 0
                                            ? "Successfully customer Updated."
                                            : "Successfully customer Created."
                                };
                            case 2:
                                return new CustomerCreationResponse
                                {
                                    ConditionalResponse = false,
                                    ResultResponse = result.ReturnValue,
                                    Merssage = "Customer already existed in db with given name."
                                };
                            case 3:
                                return new CustomerCreationResponse
                                {
                                    ConditionalResponse = false,
                                    ResultResponse = result.ReturnValue,
                                    Merssage = "Updating failed to Customer. Customer not existed in db."
                                };
                            case 5:
                                return new CustomerCreationResponse
                                {
                                    ConditionalResponse = false,
                                    ResultResponse = result.ReturnValue,
                                    Merssage = "Customer creation count elapsed."
                                };
                            case -1:
                                return new CustomerCreationResponse
                                {
                                    ConditionalResponse = false,
                                    ResultResponse = result.ReturnValue,
                                    Merssage = "Error."
                                };
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("CreateCustomerAsync :: CustomerId:- {0} :: CustomerName:- {1}", request.Id,
                    request.Name, ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return response;
        }

        private int GenerateRandomNo()
        {
            int _min = 1000;
            int _max = 9999;
            Random _rdm = new Random();
            return _rdm.Next(_min, _max);
        }

