        private Dictionary<string, object> buildCreateCustomerRequest(CustomerCreationRequest request)
        {
            var DitionParams = new Dictionary<string, object>();
            try
            {
                if (request != null)
                {
                    var format = DateTime.Now.GetDateTimeFormats();
                    DitionParams = new Dictionary<string, object>
                    {
                        {"@Id", request.Id},
                        {"@Name", request.Name},
                        {"@Address1", request.Address1},
                        //  {"@Address2", request.Address2 ?? ""},
                        //  {"@City", request.City},
                        //  {"@State", request.State},
                        //   {"@Country", request.Country},
                        //  {"@Pin", request.Pin},
                        {"@TechnicalEmail", request.TechnicalEmail},
                        {"@TechnicalPhone", request.TechnicalPhone},
                        {"@BusinessEmail", request.BusinessEmail},
                        {"@BusinessPhone", request.BusinessPhone},
                        {"@Mobile", request.Mobile},
                        {"@Fax", request.Fax ?? ""},
                        {"@Email", request.Email},
                        {"@ContactPerson", request.ContactPerson},
                        {"@Logo", request.Logo ?? ""},
                        {"@FooterNotes", request.FooterNotes ?? ""},
                        {"@CustomerType", request.CumtomerType},
                        {"@CreateToCCount", request.CreateToCustomerCount},
                        //  {"@ExpiryDate", DateTime.ParseExact(request.ExpiryDate.Replace("-", "/"), "MM/dd/yyyy", null) },
                        {"@ParentId", (request.ParentId > 0) ? request.ParentId : 0},
                        {"@Status", (request.Status) ? 1 : 0},
                        {"@AcmId", request.AcmId > 0 ? (object) request.AcmId : DBNull.Value},
                        // {"@Remarks", request.Remarks ?? ""},
