        public async Task<ADResponse> ValidateIsUserExistedOrNot(ReUsableRequest request)
        {
            Logger.InfoFormat("ValidateIsUserExistedOrNot :: Started :: {0}", request.UserId);
            try
            {
                if (request.IsLdap)
                {
                    //To Fix Warning:'System.Configuration.ConfigurationSettings.AppSettings' is obsolete: 'This method is obsolete, it has been replaced by System.Configuration!System.Configuration.System.Configuration.ConfigurationManager.AppSettings'
                    //ConfigurationSettings changed to ConfigurationManager on 13Dec2019
                    using (
                    var domain = new PrincipalContext(ContextType.Domain,
                        System.Configuration.ConfigurationManager.AppSettings["ADServiceConnString"],
                        System.Configuration.ConfigurationManager.AppSettings["ADUser"], System.Configuration.ConfigurationManager.AppSettings["ADPassword"]))
                    {
                        var identity = UserPrincipal.FindByIdentity(domain, IdentityType.SamAccountName, (domain + "\\" + request.UserName));
                        if (identity != null)
                        {
                            using (var dbConsumer = new CoreDBConsumer())
                            {
                                var user =
                                    await
                                        dbConsumer.DbConsumerForMultiItems<DataTable>("GetUserByUserName",
                                            SqlEventTypes.Select,
                                            new Dictionary<string, object> { { "@UserName", request.UserName } });
                                if (user != null)
                                {
                                    if (user[0].Rows.Count > 0)
                                    {
                                        return new ADResponse { IsValidLdapUser = true, Message = "User already existed in db." };
                                    }
                                }
                                return new ADResponse { IsValidLdapUser = true };
                            }
                        }
                        return new ADResponse { IsValidLdapUser = false, Message = "User doesn't existed in active directory." };
                    }
                }
                else
                {
                    using (var dbConsumer = new CoreDBConsumer())
                    {
                        var allUsers =
                            await
                                dbConsumer.DbConsumerForMultiItems<DataTable>("GetUserByUserName", SqlEventTypes.Select,
                                    new Dictionary<string, object> { { "@UserName", request.UserName } });
                        if (allUsers[0] != null)
                        {
                            if (allUsers[0].Rows.Count > 0)
                            {
                                return new ADResponse { Message = "User already existed in db." };
                            }
                        }
                        return new ADResponse { IsValidLdapUser = true };
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("ValidateIsUserExistedOrNot :: {0}, Error:: {1}", request.UserName, ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return new ADResponse { IsValidLdapUser = false, Message = "Invalid User." };
        }


