        private Dictionary<string, object> buildUpdateParams(UpdateUserRequest request)
        {
            Logger.InfoFormat("buildUpdateParams :: Started :: {0}", request.UserId);
            var buildparams = new Dictionary<string, object>();
            try
            {
                switch (request.command)
                {
                    case "Add":
                        request.EventType = 1;
                        request.UserName = AppInternalEncKey.Decrypt(request.UserName, false);
                        if (!request.Ldap)
                            request.Hashkey = new PHashSecurity256().HashPassword(request.UserName, request.Password);
                        else
                            request.Hashkey = new PHashSecurity256().HashPassword(request.UserName, request.UserName);
                        break;
                    case "Save":
                        request.EventType = 2;
                        if (!string.IsNullOrWhiteSpace(request.UserName))
                            request.UserName = AppInternalEncKey.Decrypt(request.UserName, false);
                        break;
                    case "Pending":
                        request.EventType = 3;
                        break;
                    case "Reject":
                        request.EventType = 3;
                        break;
                }

                buildparams = new Dictionary<string, object>
                {
                    {"@USERID", request.UserId},
                    {"@strFirstName", request.FirstName ?? ""},
                    //{"@strMiddleName", request.MiddleName ?? ""},
                    {"@strLastName", request.LastName ?? ""},
                    {"@strUserName", request.UserName ?? ""},
                    {"@strPassword", request.Password ?? ""},
                    {"@strEmail", request.Mail ?? ""},
                    {"@strMobile", request.MobileNo ?? ""},
                    {"@CustomerID", request.CustomerId},
                    {"@DivisionID", request.divisionid},
                    {"@RoleID", request.RoleId},
                    {"@HttpFlg", request.Http},
                    {"@WebFlg", request.Web},
                    {"@SMPPFlg", request.Smpp},
                    {"@SMTPFlg", request.Smtp},
                    {"@IsTwoFactor",request.IsTwoFactor},
                    {"@NoOfSessions", request.SessionsCount == 0 ? 1 : request.SessionsCount},
                    {"@Createdby", request.Createdby},
                    {"@UpdatedBy", request.UpdatedBy},
                    {"@ldap", request.Ldap},
                    {"@IsDefaultCustomer", request.IsDefaultCustomer},
                    {"@hashKey", request.Hashkey ?? ""},
                    {"@Status", request.Status},
                    {"@CurrentStatus", request.CurrentStatus},
                    {"@EVENTTYPE", request.EventType},

                    {"@ReturnValue", DBNull.Value},
                    {"@UserIp",request.UserIp}
                };
                return buildparams;
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal Error while building buildUpdateParams :: {0} ", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return buildparams;
        }

