        private Dictionary<string, object> buildUpdateParams(EditRolesCreation request)
        {
            Logger.InfoFormat("buildUpdateParams :: started ");
            var buildParams = new Dictionary<string, object>();
            try
            {
                switch (request.command)
                {
                    case "Add":
                        request.EventType = 1;
                        break;
                    case "Save":
                        request.EventType = 2;
                        break;
                    case "Approved":
                        request.EventType = 3;
                        break;
                    case "Reject":
                        request.EventType = 4;
                        break;
                }
                buildParams = new Dictionary<string, object>
                {
                    {"@RoleId", request.RoleId},
                    {"@strRolename", request.Name ?? ""},
                    // {"@strRoledesc", request.Description ?? ""},
                    {"@CustomerId", request.CustomerId},
                    {"@rolestatus", request.Status},
                    {"@CURRENTSTATUS", request.CurrentStatus},
                    {"@CreatedBy", request.CreatedBy},
                    {"@EVENTTYPE", request.EventType},

                    {"@ReturnValue", DBNull.Value},
                    {"@UserIp",request.UserIp}
                };
                return buildParams;
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal Error while executing buildUpdateParams :- {0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return buildParams;
        }

