        private List<FeatureResponse> BuildAllFeatures(DataTable table)
        {
            Logger.InfoFormat("BuildAllFeatures :: Started");
            var response = new List<FeatureResponse>();
            try
            {
                var featureIds = table.Rows.Cast<DataRow>().Select(s => Convert.ToInt32(s["Id"])).Distinct();
                //var response = new List<FeatureResponse>();
                //foreach (var item in featureIds)
                //{
                //    var drItems = table.Rows.Cast<DataRow>().Where(w => Convert.ToInt32(w["Id"]) == item);
                //    if(drItems != null)
                //    {
                //        var frItem = new FeatureResponse();
                //        frItem.SubFeatures = new List<SubFeatureResponse>();
                //        frItem.Id = item;
                //        frItem.Name = drItems.FirstOrDefault()["Name"].ToString();
                //        var sfeatureResponse = table.Rows.Cast<DataRow>().Select(s => new SubFeatureResponse { SubFeatureId = Convert.ToInt32(s["SubFeatureId"]), SubFeatureName = s["SubFeatureName"].ToString() + " - " + s["PageType"].ToString() }).ToList();
                //        frItem.SubFeatures = sfeatureResponse;
                //    }
                //}
                response = (from featureId in featureIds
                            let features =
                                table.Rows.Cast<DataRow>().Where(w => Convert.ToInt32(w["Id"]) == featureId)
                            let featur = features.FirstOrDefault()
                            select new FeatureResponse
                            {
                                Id = featureId,
                                Name = featur["Name"].ToString(),
                                SubFeatures = features.Select(s => new SubFeatureResponse
                                {
                                    SubFeatureId = Convert.ToInt32(s["SubFeatureId"]),
                                    SubFeatureName = s["SubFeatureName"].ToString() //+ " - " + s["PageType"].ToString()
                                }).ToList()
                            }).ToList();
                return response.Any() ? response : new List<FeatureResponse>();
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal Error occured while excuting BuildAllFeatures :: Error :- {0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return response.Any() ? response : new List<FeatureResponse>();
        }

        private List<FeatureResponse> BuildFeaturesByRole(List<FeatureResponse> allFeatures, DataTable selectedFeatures)
        {
            Logger.InfoFormat("BuildFeaturesByRole :: Started");
            try
            {
                var featureIds = selectedFeatures.Rows.Cast<DataRow>().Select(s => Convert.ToInt32(s["Id"])).Distinct();

                var collectionofSelectedFeatures = (from featureId in featureIds
                                                    let features =
                                                        selectedFeatures.Rows.Cast<DataRow>().Where(w => Convert.ToInt32(w["Id"]) == featureId)
                                                    let featur = features.FirstOrDefault()
                                                    select new FeatureResponse
                                                    {
                                                        Id = featureId,
                                                        Name = featur["Name"].ToString(),
                                                        SubFeatures = features.Select(s => new SubFeatureResponse
                                                        {
                                                            SubFeatureId = Convert.ToInt32(s["SubFeatureId"]),
                                                            SubFeatureName = s["SubFeatureName"].ToString() //+ " - " + s["PageType"].ToString()
                                                        }).ToList()
                                                    }).ToList();

                foreach (var featureId in featureIds)
                {
                    var aFeature = allFeatures.FirstOrDefault(f => f.Id == featureId);
                    var sFeature = collectionofSelectedFeatures.FirstOrDefault(f => f.Id == featureId);

                    foreach (var item in sFeature.SubFeatures)
                    {
                        var a = aFeature.SubFeatures.FirstOrDefault(x => x.SubFeatureId == item.SubFeatureId);
                        if (a != null)
                        {
                            a.IsChecked = true;
                        }
                    }
                }
                return allFeatures;
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal Error occured while excuting BuildFeaturesByRole :: Error :- {0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return allFeatures;
        }

