        public async Task<FeaturePrivilagesSetupMain> buildFeaturePrivilagesSetup(ReUsableRequest request)
        {
            Logger.InfoFormat("buildFeaturePrivilagesSetup :: start :: customerid:-{0},", request.CustomerId);
            try
            {
                using (var dbConsumer = new CoreDBConsumer())
                {
                    var result =
                        await
                            dbConsumer.DbConsumerForMultiItems<DataTable>(
                                "GetAllFeaturesWichIsCheckerAvailableStatus", SqlEventTypes.Select,
                                new Dictionary<string, object> { { "@CustomerId", request.CustomerId } });

                    if (result != null && result[0] != null)
                    {
                        var featuresResponse = new FeaturePrivilagesSetupMain { AllFeatures = result[0].ToList<FeaturePrivilagesSetupResponse>() };
                        var secondResultSet =
                            await
                                dbConsumer.DbConsumerForMultiItems<DataTable>(
                                    "GetAllFeaturesWichIsCheckerAvailableStatusSecondResultSet", SqlEventTypes.Select,
                                    new Dictionary<string, object> { { "@CustomerId", request.CustomerId } });
                        if (secondResultSet != null && secondResultSet[0] != null)
                        {
                            featuresResponse.FeaturesByCustomerId = BuildFeaturesByCustomerId(featuresResponse.AllFeatures, secondResultSet[0]);
                        }
                        Logger.InfoFormat("buildFeaturePrivilagesSetup ::End ::Build Featurepriviliges Setup:: {0} ", (featuresResponse));
                        return featuresResponse;
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("buildFeaturePrivilagesSetup ::custid :-{0} :: Error :- {1} ", request.CustomerId,
                    ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return new FeaturePrivilagesSetupMain();
        }

        private List<FeaturePrivilagesSetupResponse> BuildFeaturesByCustomerId(List<FeaturePrivilagesSetupResponse> allFeatures, DataTable selectedFeatures)
        {
            try
            {
                var featureIds = selectedFeatures.Rows.Cast<DataRow>().Select(s => Convert.ToInt32(s["Id"])).Distinct();
                var collectionofSelectedFeatures = (from featureId in featureIds
                                                    let features =
                                                        selectedFeatures.Rows.Cast<DataRow>().Where(w => Convert.ToInt32(w["Id"]) == featureId)
                                                    let featur = features.FirstOrDefault()
                                                    select new FeaturePrivilagesSetupResponse
                                                    {
                                                        Id = featureId,
                                                        ParentPlugin = featur["ParentPlugin"].ToString(),
                                                        Plugin = featur["PlugiN"].ToString(),
                                                        PageType = featur["PageType"].ToString(),
                                                        IsCheckerRequier = Convert.ToBoolean(featur["IsCheckerRequier"].ToString()),
                                                        ActiveStatus = Convert.ToBoolean(featur["ActiveStatus"].ToString())
                                                    }).ToList();
                allFeatures = allFeatures.GroupBy(g => g.Id).Select(s => s.First()).ToList();
                allFeatures.ForEach(x =>
                {
                    x.IsCheckerRequier = false;
                    x.ActiveStatus = false;
                });

                foreach (var item in collectionofSelectedFeatures)
                {
                    var selFeature = allFeatures.FirstOrDefault(x => x.Id == item.Id);
                    if (selFeature != null)
                    {
                        selFeature.IsCheckerRequier = item.IsCheckerRequier;
                        selFeature.ActiveStatus = item.ActiveStatus;
                    }
                }
                return allFeatures;
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("BuildFeaturesByCustomerId :: Error :- {0} ", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return allFeatures;
        }

