                                });
                    Logger.InfoFormat(
                        "IsDepartmentExistedByName :: End ::Is Department Exist By Name :: Error :-{0}:: DepId:-{2} ",
                        (response.ReturnValue > 0));

                    var model = new { IsValid = false, Message = "" };

                    bool Isv = false;
                    string strMsg = "";

                    if (response.ReturnValue == 0)
                    {
                        Isv = true;
                        strMsg = "Valid";
                    }

                    if (response.ReturnValue > 0)
                    {
                        Isv = false;
                        strMsg = "Department already existed in db.";
                    }
                    return new MessageResponse
                    {
                        IsValid = Isv,
                        Message = strMsg
                    };
                }
            }
            catch (Exception ex)
            {
                var error = ex.ToString();
                Logger.ErrorFormat("IsDepartmentExistedByName ::DepId :-{0} :: Error :- {1} ", request.DepId,
                    ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return new MessageResponse
            {
                IsValid = false
            };
        }
