        private Dictionary<string, object> buildUpdateParams_FWords(SetFWReq request)
        {
            //added/updated by coming from session which is userid
            var buildParams = new Dictionary<string, object>();
            try
            {
                buildParams = request.command.Equals("Add")
                    ? new Dictionary<string, object>
                    {
                        {"@nId", request.nId},
                        {"@strWord", request.strWord},
                        //{"@strReplaceWord",request.strReplaceWord},
                        {"@nStatus", request.nStatus},
                        {"@CreatedBy", request.CreatedBy},
                        {"@CurrentStatus", request.CurrentStatus},
                        {"@strDupliWords", ""},
                        {"@UserIp",request.UserIp} ,
                        {"@ReturnValue", DBNull.Value}
                    }
                    : new Dictionary<string, object>
                    {
                        {"@nId", request.nId},
                        {"@strWord", request.strWord},
                        // {"@strReplaceWord",request.strReplaceWord},
                        {"@nStatus", request.nStatus},
                        {"@CreatedBy", request.CreatedBy},
                        {"@strDupliWords", ""},
                        {"@Currentstatus", request.CurrentStatus},

                        {"@ReturnValue", DBNull.Value},
                        {"@UserIp",request.UserIp}
                    };
                return buildParams;
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("buildUpdateParams_FWords :: {0} :: Error :: {1}", request.nId, ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return buildParams;
        }

