        public async Task<Int32> InsertDNDList(InsertDNDList request)
        {
            Logger.InfoFormat("InsertDNDList :: Started :: {0}", request.nId);
            DataTable dt = new DataTable();
            try
            {
                using (var dbConsumer = new CoreDBConsumer())
                {
                    var dnd =
                        await
                            dbConsumer.DbConsumerForMultiItems<DataTable>("SetDNDListSingleMobileno",
                                SqlEventTypes.Insert,
                                new Dictionary<string, object>
                                {
                                    {"@nId", request.nId},
                                    {"@strMobileNo", request.strMobileNo},
                                    {"@strName", request.strName},
                                    {"@nUserId", request.nUserId},
                                    {"@nCustomerId", request.nCustomerId},
                                    {"@CurrentStatus", request.Currentstatus},
                                    {"@CreatedBy", request.CreatedBy},
                                    {"@ReturnValue", DBNull.Value},
                                    {"@UserIp",request.UserIp}

                                });
                    Logger.InfoFormat("InsertDNDList :: End :: Insert DND  :: {0} ", dnd.Count);
                    if (System.Configuration.ConfigurationManager.AppSettings["onPremise"] != "false" || System.Configuration.ConfigurationManager.AppSettings["onPremise"] == "")
                    {
                        if (request.Currentstatus == 1)
                        {
                            //AdminNotificationCallOne("DND"); request.strMobileNo.Split(',').ToArray()
                            var mobNos = new string[1];
                            mobNos[0] = request.strMobileNo;
                            DNDNotification("add", "dnd", mobNos);
                        }
                    }
                    Logger.InfoFormat("InsertDNDList :: End :: Insert DND  :: {0} ", request.nId);
                    return
                        Convert.ToInt32(!string.IsNullOrWhiteSpace(dnd[0].Rows[0][1].ToString())
                            ? dnd[0].Rows[0][1]
                            : "0");
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("InsertDNDList :: {0} :: Error :: {1}", request.nId, ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return 0;
        }

        public async Task<int> ImportDNDS(ImportDNDRequest request)
        {
            Logger.Info("IMPORTDNDSTART");
            try
            {
                using (var _consumer = new CoreDBConsumer())
                {
                    request.DNDList.RemoveAll(x => x.MobileNo == null || x.MobileNo == "");

                    var xEle = new XElement("ImportDNDS",
                                 from ImportDND in request.DNDList
                                 select new XElement("ImportDND",
                                new XElement("Name", ImportDND.Name ?? ""),
                               new XElement("MobileNo", ImportDND.MobileNo)
                           ));

                    var resp = await _consumer.DbConsumer<ReUsableResponse>("SetDND_Import", SqlEventTypes.Select,
                         new Dictionary<string, object>(){
                                             {"@xmlDND", xEle.ToString()},
                                             {"@ReturnValue", DBNull.Value},
                                             {"@CustomerId",request.Id},
                                             {"@UserId",request.Createdby},
                                             {"@createdby",request.Createdby},
                                             {"@currentstatus",request.CurrentStatus}

                         });
                    Logger.Info("IMPORTDNDEND");
                    if (System.Configuration.ConfigurationManager.AppSettings["onPremise"] != "false" || System.Configuration.ConfigurationManager.AppSettings["onPremise"] == "")
                    {
                        if (request.CurrentStatus == 1)
                        {
                            //AdminNotificationCallOne("DND");
                            DNDNotification("add", "dnd", request.DNDList.Select(s => s.MobileNo).ToArray());
                        }
                    }
                    return resp.NRETVAL = resp.ReturnValue;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal error occured while executing ImportDNDS :: Error :: {0} ", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return 0;
        }

