                               new XElement("IncomeGroup", Externaldb.IncomeGroup),
                               new XElement("CityofResidence", Externaldb.CityofResidence),
                               new XElement("VMDB", (Externaldb.VMDB == null ? "1" : Externaldb.VMDB))
                           ));
                    var resp = await _consumer.DbConsumer<ReUsableResponse>("SetExternal_Import", SqlEventTypes.Select,
                         new Dictionary<string, object>(){
                                             {"@xmlExternal", xEle.ToString()},
                                             {"@createdby", request.Createdby},
                                             {"@ReturnValue", DBNull.Value}
                         }, false, DBs.ExternalDB);
                    Logger.Info("ImportExternalDB End");

                    //return resp.ReturnValue;
                    return resp.ReturnValue + "$" + resp.INSERTEDCOUNT + "$" + resp.FAILEDCOUNT + "$" + resp.TOTALCOUNT;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal error occured while executing ImportExternalDB :: Error :: {0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return "0";
        }

