        private Dictionary<string, object> buildUpdateParams(UpdateLockStatus request)
        {
            var buildParams = new Dictionary<string, object>();
            try
            {
                switch (request.command)
                {
                    case "Select":
                        request.EventType = 0;
                        break;
                    case "Save":
                        request.EventType = 1;
                        break;
                    case "Approved":
                        request.EventType = 2;
                        break;
                    case "Reject":
                        request.EventType = 3;
                        break;
                }
                buildParams = new Dictionary<string, object>
                {
                    {"@USERID", request.UserId},
                    {"@UPDATEDBY", request.UpdatedBy},
                    {"@EVENTTYPE", request.EventType},

                    {"@ReturnValue", DBNull.Value},
                    {"@UserIp",request.UserIp}
                };
                return buildParams;
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("buildUpdateParams :: Error :: {0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return buildParams;
        }

