        public async Task<List<Int32>> SaveHlrLookUpResult(List<HlrLookupRequest> request)
        {
            Logger.Info("SaveHlrLookUpResult :: Started");
            try
            {
                var returnvalues = new List<Int32>();

                using (var dbconsumer = new CoreDBConsumer())
                {
                    foreach (var item in request)
                    {
                        var hlr = await dbconsumer.DbConsumer<Int32>("SaveHlrLookup", SqlEventTypes.Insert,
                                  new Dictionary<string, object>
                          {
                            {"@Id", item.Id},
                            {"@CustomerId", item.CustomerId},
                            {"@UserId", item.UserId},
                            {"@SenderId", item.SenderId},
                            {"@LookUpEnableForCampaigns", item.LookUpEnableForCampaigns},
                            {"@LookUpEnableForAlerts", item.LookUpEnableForAlerts},
                            {"@HoldPeriodForAbsent", item.HoldPeriodForAbsent},
                            {"@LookUpReAttempt", item.LookUpReAttempt},
                            {"@SendSMSInRoaming", item.SendSmsInRoaming},
                            {"@IsActive", item.IsActive},
                            {"@CurrentStatus", item.CurrentStatus},
                            {"@CreatedBy", item.CreatedBy},
                            {"@RejectNote", item.RejectNote ?? ""},
                            {"@ReturnValue", DBNull.Value}
                          });
                        if (item.CurrentStatus == 1)
                        {
                            AdminNotificationCallOne("HLR");
                        }
                        returnvalues.Add(hlr);
                        // hlr;
                    }
                    Logger.Info("SaveHlrLookUpResult :: End");
                    return returnvalues;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal error occured while executing SaveHlrLookUpResult :: Error :: {0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return new List<int>();
        }


