        public async Task<string> OperatorAddEdit(AddEditOperator request)
        {
            Logger.InfoFormat("OperatorAddEdit :: Started :: {0}", request.CNTID);
            int opeartorid = request.OPRID;
            var SeriesLegs = request.Series;
            int countOPLeg = SeriesLegs.Count;
            var command = string.Empty;
            request.command = opeartorid == 0 ? "Add" : "Edit";

            /*
             * 
             * for first time add there is no need to call detailoperator_Delete.
             * for edit we should call detailopeartor_delete then editforOPERATOR and insertforDETAILOPERATOR
             *   */
            DataTable dt = new DataTable();
            string s = "";

            try
            {
                int autoperid = 0;
                using (var dbConsumer = new CoreDBConsumer())
                {
                    var VarOpid =
                        await
                            dbConsumer.DbConsumerForMultiItems<DataTable>(
                                request.command.Equals("Add") ? "SetOperators" : "UpdateOperators",
                                request.command.Equals("Add") ? SqlEventTypes.Insert : SqlEventTypes.Update,
                                buildAddEditParamOperator(request));

                    dt = VarOpid[0];

                    if (dt.Rows[0][0].ToString() == "0" && dt.Rows[0][1].ToString() == "1")
                    {
                        s = dt.Rows[0][0].ToString() + "," + dt.Rows[0][1].ToString();
                        return s;
                    }
                    if (countOPLeg != 0)  //insertions going into detailoperator table. happend in detail operator.
                    {
                        //delete detailoperator based on operator id
                        if (request.command != "Add")
                        {
                            var deloper =
                                await
                                    dbConsumer.DbConsumer<ReUsableResponse>("DeleteOperators_Series",
                                        SqlEventTypes.Select, new Dictionary<string, object>
                                        {
                                            {"@NOPID", opeartorid},
                                            {"@updatedby", request.USERID},
                                            {"@UserIp",request.UserIp},
                                            {"@ReturnValue", 0}
                                        });
                        }


                        if (VarOpid[0] != null)
                        {
                            dt = VarOpid[0];
                            autoperid = Convert.ToInt32(VarOpid[0].Rows[0][0]);
                            //new insertions into detail operator table
                            foreach (var leg in SeriesLegs)
                            {
                                var ins =
                                    await
                                        dbConsumer.DbConsumerForMultiItems<DataTable>("SetOperatorDetails", SqlEventTypes.Select,
                                            new Dictionary<string, object>
                                            {
                                                {"@NOPID", (request.command == "Add") ? autoperid : opeartorid},
                                                {"@STRSERIES", leg.series ?? ""},
                                                {"@NLEN", leg.mlength},
                                                {"@NADDEDBY", request.USERID},
                                                {"@NCountryCode", request.CNTID},
                                                {"@ReturnValue", 0}
                                            });

                                if (ins[0].Rows[0][0].ToString() == "9")
                                {
                                    s = "9,9";
                                    //delete information from Operators also
                                    if (request.command.Equals("Add"))
                                    {
                                        // autoperid
                                        var DOper = await dbConsumer.DbConsumer<Int32>("DelOperator", SqlEventTypes.Delete, new Dictionary<string, object>
                                             {
                                               {"@OperatorId", autoperid}
                                             });
                                    }
                                    return s;
                                }
                            }
                        }
                        if (dt != null)
                        {
                            s = dt.Rows[0][0].ToString() + "," + dt.Rows[0][1].ToString();
                        }
                    }

                    else
                    {
                        var dop = await dbConsumer.DbConsumer<Int32>("DeleteOperators_Series", SqlEventTypes.Delete, new Dictionary<string, object>
                             {
                               {"@NOPID", opeartorid},
                               {"@updatedby", request.USERID},
                               {"@ReturnValue",0}
                             });

                        if (dt != null)
                        {
                            s = dt.Rows[0][0].ToString() + "," + dt.Rows[0][1].ToString();
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("ChangeStatusOP :: {0} :: Error :: {1}", request.CNTID, ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }

            if (request.CurrentStatus == 1)
            {
                AdminNotificationCallOne("Client");
            }
            return s;
        }



