        private Dictionary<string, object> buildAddEditParamOperator(AddEditOperator request)
        {
            Logger.InfoFormat("buildAddEditParamOperator :: Started :: {0}", request.CNTID);
            //added/updated by coming from session which is userid
            Logger.Info("buildAddEditParamOperator :: Started");
            var buildParams = new Dictionary<string, object>();
            try
            {
                buildParams = request.command.Equals("Add")
                    ? new Dictionary<string, object>
                    {
                        {"@STRNAME", request.OPRNAME},
                        {"@STRCOUNTRYCODE", request.CNTID},
                        //{"@STRDESC", request.OPRDESC ?? ""},
                        {"@NADDEDBY", request.USERID},
                        {"@CurrentStatus", request.CurrentStatus},
                        {"@ReturnValue", 0},

                        {"@NOPID", 0},
                        {"@UserIp",request.UserIp}
                    }
                    : new Dictionary<string, object>
                    {
                        {"@NID", request.OPRID},
                        {"@STRNAME", request.OPRNAME},
                        {"@STRCOUNTRYCODE", request.CNTID},
                        //{"@STRDESC", request.OPRDESC ?? ""},
                        {"@CurrentStatus", request.CurrentStatus},
                        {"@NUPDATEDBY", request.USERID},

                        {"@ReturnValue", 0},
                        {"@UserIp",request.UserIp}
                    };
                return buildParams;
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal Error :: {0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return buildParams;
        }

