        /// <summary>
        /// Method Name : ChangeStatusSMSCINTL
        /// Created By : 
        /// Created On : 05/10/2016
        /// Purpose : To chnage the status of a selectd Smsc
        /// Modified By : 
        /// Modified On :
        /// Details of Modification :  
        /// </summary>
        public List<string> ChangeStatusSMSCINTL(UpdateSMSCINTLStatusRequest request)
        {
            Logger.InfoFormat("ChangeStatusSMSCINTL :: Started :: {0}", request.strSMSCIds);
            var failedIds = new List<string>();
            try
            {
                using (var _consumer = new CoreDBConsumer())
                {
                    var Ids = request.strSMSCIds.Split(',').Where(w => !string.IsNullOrWhiteSpace(w)).ToList();
                    var cstas = request.chgstatus.Split(',');
                    int i = 0;

                    foreach (var valId in Ids)
                    {
                        var res = _consumer.DbConsumer<ReUsableResponse>("UpdateSMSCIntlStatus", SqlEventTypes.Select,
                            new Dictionary<string, object>(){
                                {"@strSMSCIds",valId.ToString()},
                                {"@createdby",request.createdby},
                                {"@nStatus",cstas[i]=="Active" ? 0 : 1},

                                {"@ReturnValue",DBNull.Value},
                                {"@UserIp",request.UserIp}
                                });

                        if (res.Result.ReturnValue == 5)
                        {
                            failedIds.Add(valId);
                        }
                        i++;
                    };
                    return failedIds;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("ChangeStatus :: {0} :: Error :: {1}", request.strSMSCIds, ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return null;
        }


