        public async Task<List<int>> InsertSMSCIntlConnectionDetailsSMPP(SetConnectionsSMPPRequest request)
        {
            Logger.InfoFormat("InsertSMSCIntlConnectionDetailsSMPP :: Started :: {0}", request.strUserId);
            try
            {
                var outParam = 0;
                int ntype = request.ncontype;
                int swicval = 0;
                if (Convert.ToInt32(SmscConnectionType.SMPP) == ntype)
                {
                    swicval = 1;
                }
                else if (Convert.ToInt32(SmscConnectionType.HTTP) == ntype)
                {
                    swicval = 2;
                }
                List<int> objres = new List<int>();
                using (var _consumer = new CoreDBConsumer())
                {
                    int retval = SaveSMSCIntlDetails(_consumer, request, ref outParam);
                    if (retval == -4 || retval == -1)
                    {
                        /* 4 duplicate,-1 ERROR,3 smscname mapped with a routename in routemaster */
                        objres.Add(retval);
                        return objres;
                    }
                    switch (swicval)
                    {
                        case 1:
                            objres.Add(SaveSMSCConnectionsIntlDetails(_consumer, request, ref outParam));
                            break;
                        case 2:
                            /* 8 duplicate -1 error in insert */
                            objres.Add(SaveSMSCIntlConnectionDetailsHTTP(_consumer, request, ref outParam));
                            break;
                    }
                    return objres;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("InsertSMSCIntlConnectionDetailsSMPP :: Error :: {0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return new List<int>();
        }

        private int SaveSMSCIntlDetails(CoreDBConsumer _consumer, SetConnectionsSMPPRequest request, ref int returnValue)
        {
            //returnressmscid = request.n;
