        public async Task<String> AddEditSenderIDShortCode(AddEditSender request)
        {
            Logger.InfoFormat("AddEditSenderIDShortCode :: Started :: {0}", request.sId);
            var command = string.Empty;
            string status = "";

            if (request.sId == 0)
            { request.command = "Add"; }
            else
            { request.command = "Edit"; }
            try
            {
                DataTable dt = new DataTable();
                using (var dbConsumer = new CoreDBConsumer())
                {
                    var SenderIDShortCode =
                        await
                            dbConsumer.DbConsumerForMultiItems<System.Data.DataTable>(
                                request.command.Equals("Add") ? "SetSender" : "UpdateSender",
                                request.command.Equals("Add") ? SqlEventTypes.Insert : SqlEventTypes.Update,
                                buildAddEditParamSenderIDShortCode(request));
                    Logger.InfoFormat("AddEditSenderIDShortCode :: End :: AddSenderId/ShortCode :: {0} ",
                        SenderIDShortCode);
                    dt = SenderIDShortCode[0];
                    if (dt != null)
                        status = dt.Rows[0][0].ToString() + "," + dt.Rows[0][1].ToString();
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("AddEditSenderIDShortCode :: {0} :: Error :: {1}", request.sId, ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            if (request.CurrentStatus == 1)
            {
                AdminNotificationCallOne("SMPPSenders");
                AdminNotificationCallOne("Route");
            }
            return status;
        }


