        private Dictionary<string, object> buildAddEditParamSenderIDShortCode(AddEditSender request)
        {
            //added/updated by coming from session which is userid
            Logger.Info("buildAddEditParamSenderIDShortCode :: Started");
            var buildParams = new Dictionary<string, object>();
            try
            {
                buildParams = request.command.Equals("Add")
                    ? new Dictionary<string, object>
                    {
                        {"@NTYPE", request.sType},
                        {"@STRCODE", request.sCode},
                        {"@STRDIVDESC", request.sDescription ?? ""},
                        {"@NCREATEDBY", request.sCreatedBy},
                        {"@CurrentStatus", request.CurrentStatus},
                        {"@NSHORTCODETYPE", request.sShortCodeType},
                        {"@NSENDERIDTYPE", request.sSenderIDType},
                        {"@NByPassDND", request.sDndByPass},
                        {"@NRECID", 1},

                        {"@ReturnValue", 0},
                        {"@UserIp",request.UserIp}
                    }
                    : new Dictionary<string, object>
                    {

                        {"@NSENDERID", request.sId},
                        {"@NTYPE", request.sType},
                        {"@STRCODE", request.sCode},
                        {"@STRDIVDESC", request.sDescription ?? ""},
                        {"@NSTATUS", request.status},
                        {"@NUPDATEDBY", request.sCreatedBy},
                        {"@CurrentStatus", request.CurrentStatus},
                        {"@NSHORTCODETYPE", request.sShortCodeType},
                        {"@NSENDERIDTYPE", request.sSenderIDType},
                        {"@NDNDBYPASS", request.sDndByPass},

                        {"@ReturnValue", 0},
                        {"@UserIp",request.UserIp}
                    };
                return buildParams;
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("buildAddEditParamSenderIDShortCode :: Error :: {0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return buildParams;
        }

