        public async Task<Int32> SIDSCCheck(AorRSIDSC request)
        {
            Logger.InfoFormat("SIDSCCheck :: Started :: {0}", request.id);
            try
            {
                using (var dbConsumer = new CoreDBConsumer())
                {
                    var UpdateSIDSC = await dbConsumer.DbConsumer<ReUsableResponse>("ApproveOrRejectSender", SqlEventTypes.Select, buildUpdateParams_SIDSCCheck(request));
