                    Logger.InfoFormat("SIDSCCheck :: End :: Update SIDSCheck :: {0} ", UpdateSIDSC.ReturnValue);
                    return UpdateSIDSC.ReturnValue;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("SIDSCCheck :: {0} :: Error :: {1}", request.id, ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return 0;
        }
