        public async Task<string> SaveOrUpdateMapSender(MapSenderRequest request)
        {
            Logger.InfoFormat("SaveOrUpdateMapSender :: Started :: {0} :: {1} :: {2}", request.CustomerId, request.UserId, request.MapSenderId);
            try
            {
                var result = new List<KeyValuePair<string, string>>();
                var allUsers = request.UserId.Split(',').ToList();
                if (allUsers.Count > 1)
                {
                    allUsers = allUsers.Where(w => !string.IsNullOrWhiteSpace(w) && !w.Equals("0")).ToList();
                }
                if (request.MapSenderId > 0)
                {
                    using (var dbConsumer = new CoreDBConsumer())
                    {
                        allUsers.ForEach(f =>
                        {
                            request.UserId = string.Empty;
                            request.UserId = f;
                            request.CountrySeries.ForEach(x =>
                            {
                                var updateMapSender =
                                    dbConsumer.DbConsumer<Int32>("UpdateSIDMapper",
                                        SqlEventTypes.Update,
                                        new Dictionary<string, object>
                                        {
                                        {"@Id", request.MapSenderId},
                                        {"@NCUSTID", request.CustomerId},
                                        {"@NUSERID", Convert.ToInt32(request.UserId)},
                                        {"@NSID", x.SenderId},
                                        {"@STRDISSID", x.DispatchSenderId.Trim()},
                                        {"@NCOUNTRYID", Convert.ToInt32(x.CountryName)},
                                        {"@NCREATEDBY", request.CreatedBy},
                                        {"@NFLAG", 0},
                                        {"@NDISPATCHTYPE", x.DispatchType.Trim()},
                                        {"@PreferredRoute", x.Route ?? ""},
                                        {"@CurrentStatus", request.CurrentStatus},
                                        {"@ShortCode", x.ShortCode.Trim()},
                                        {"@DNSBYPASS", request.DNSBYPASS},
                                        {"@DNDBYPASS", request.DNDBYPASS},
                                        {"@CheckHLR", request.CheckHLR},
                                        {"@ReturnValue", DBNull.Value},
                                        {"@UserIp",request.UserIp}
                                        }).Result;
                                var keypair = new KeyValuePair<string, string>(x.DisplayName,
                                    updateMapSender.ToString());
                                Logger.Info("Return Value:: " + updateMapSender);
                                result.Add(keypair);
                            });
                        });
                        Logger.InfoFormat("SaveOrUpdateMapSender :: End :: SaveOrUpdateMapSender :: {0} ", (result.FirstOrDefault()));
                        // return result.Count == request.CountrySeries.Count ? 1 : 0;
                        if (request.CurrentStatus == 1)
                        {
                            AdminNotificationCallOne("SMPPSenders");
                            AdminNotificationCallOne("Route");
                        }
                        var res = string.Empty;
                        foreach (var mo in result)
                        {
                            if (mo.Value == "1")
                            {
                                res += "IsValid=true:Message=Information Updated Successfully:" + mo.Key + "|-|";
                            }
                            if (mo.Value == "0" || mo.Value == "-1")
                            {
                                res += "IsValid=false:Message=Information update was unsuccessful:" + mo.Key + "|-|";
                            }
                        }
                        return res;
                    }
                }
                else
                {
                    using (var dbConsumer = new CoreDBConsumer())
                    {
                        allUsers.ForEach(f =>
                        {
                            request.UserId = string.Empty;
                            request.UserId = f;
                            request.CountrySeries.ForEach(x =>
                            {
                                var updateMapSender =
                                    dbConsumer.DbConsumer<ReUsableResponse>("UpdateSIDMapper",
                                        SqlEventTypes.Select,
                                        new Dictionary<string, object>
                                        {
                                        {"@Id", request.MapSenderId},
                                        {"@NCUSTID", request.CustomerId},
                                        {"@NUSERID", Convert.ToInt32(request.UserId)},
                                        {"@NSID", x.SenderId},
                                        {"@STRDISSID", x.DispatchSenderId.Trim()},
                                        {"@NCOUNTRYID", Convert.ToInt32(x.CountryName)},
                                        {"@NCREATEDBY", request.CreatedBy},
                                        {"@NFLAG", 0},
                                        {"@NDISPATCHTYPE", x.DispatchType.Trim()},
                                        {"@PreferredRoute", x.Route ?? ""},
                                        {"@CurrentStatus", request.CurrentStatus},
                                        {"@ShortCode", x.ShortCode.Trim()},
                                        {"@DNSBYPASS", request.DNSBYPASS},
                                        {"@DNDBYPASS", request.DNDBYPASS},
                                        {"@CheckHLR", request.CheckHLR},
                                        {"@ReturnValue", DBNull.Value},
                                        {"@UserIp",request.UserIp}
                                        }).Result;
                                var keypair = new KeyValuePair<string, string>(x.DisplayName,
                                    updateMapSender.ReturnValue.ToString());
                                Logger.Info("ReturnError:: " + updateMapSender.ERROR);
                                result.Add(keypair);
                            });
                        });
                        Logger.InfoFormat("SaveOrUpdateMapSender :: End :: SaveOrUpdateMapSender :: {0} ", (result.FirstOrDefault()));
                        // return result.Count == request.CountrySeries.Count ? 1 : 0;
                        if (request.CurrentStatus == 1)
                        {
                            AdminNotificationCallOne("SMPPSenders");
                            AdminNotificationCallOne("Route");
                        }
                        var res = string.Empty;
                        foreach (var mo in result)
                        {
                            if (mo.Value == "1")
                            {
                                res += "IsValid=true:Message=Information Saved Successfully:" + mo.Key + "|-|";
                            }
                            if (mo.Value == "9")
                            {
                                res += "IsValid=false:Message=Map Sender already exist:" + mo.Key + "|-|";
                            }
                            if (mo.Value == "10" || mo.Value == "16" || mo.Value == "17" || mo.Value == "18")
                            {
                                res += "IsValid=false:Message=Preferred route not found :" + mo.Key + "|-|";
                            }
                            //if (mo.Value == "12")
                            //{
                            //    //res += "IsValid=false:Message=User already mapped with OpenSenderId:" + mo.Key + "|-|";
                            //    res += "IsValid=false:Message=User already mapped with Masking Sender:" + mo.Key + "|-|";
                            //}
                            //if (mo.Value == "15")
                            //{
                            //    //res += "IsValid=false:Message=User already mapped with Masking Sender:" + mo.Key + "|-|";
                            //    res += "IsValid=false:Message=User already mapped with OpenSender:" + mo.Key + "|-|";

                            //}
                            if (mo.Value == "16" || mo.Value == "11")
                            {
                                res += "IsValid=false:Message= Default route not found for selected country: " + mo.Key + "|-|";
                            }
                        }
                        return res;
                    }
                }
            }
            catch (Exception ex)
            {
                var error = ex.ToString();
                Logger.ErrorFormat("SaveOrUpdateMapSender :: {0} :: Error :: {1}", request.CustomerId, request.UserId,
                    request.MapSenderId, ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return string.Empty;
        }

        public List<string> ChangeStatusMS(ReUsableRequest request)
        {
            Logger.InfoFormat("ChangeStatusMS :: Started :: {0} ", request.UserId);
            var failedIds = new List<string>();
            try
            {
                using (var dbConsumer = new CoreDBConsumer())
                {
                    var Ids = request.UserIds.Split(',').Where(w => !string.IsNullOrWhiteSpace(w)).ToList();

                    int i = 0;
                    foreach (var valId in Ids)
                    {
                        var res = dbConsumer.DbConsumer<ReUsableResponse>("MAPSENDERActiveInactive", SqlEventTypes.Select,
                            new Dictionary<string, object>(){
                            {"@Id", valId.ToString()},

                            {"@Updatedby", request.UpdatedBy},
                            {"@UserIp",request.UserIp}
                            });
                        if (res.Result.ReturnValue == 0 || res.Result.ReturnValue == 1)
                        {
                            failedIds.Add(valId);
                        }
                        i++;
                    };
                    return failedIds;
                }
            }
            catch (Exception ex)
            {
                var error = ex.ToString();
                Logger.ErrorFormat("ChangeStatus :: {0} :: Error :: {1}", request.UserIds, ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return null;
        }

