        /// <summary>
        /// Method Name : ChangeStatusUserRoute
        /// Created By :
        /// Created On : 
        /// Purpose : To Change the status of selected routes
        /// Modified By : 
        /// Modified On :
        /// Details of Modification :  
        /// </summary>  
        /// 

        public List<string> ChangeStatusUserRoute(CheckDefaultRouteOnRequest request)
        {
            Logger.InfoFormat("ChangeStatusUserRoute :: Started :: {0} :: {1}", request.ROUTEIDS, request.USERID);
            var failedIds = new List<string>();
            try
            {
                using (var _consumer = new CoreDBConsumer())
                {
                    var Ids = request.ROUTEIDS.Split(',').Where(w => !string.IsNullOrWhiteSpace(w)).ToList();
                    var mstas = request.chgstatus.Split(',');

                    int i = 0;
                    foreach (var valId in Ids)
                    {
                        var res = _consumer.DbConsumer<ReUsableResponse>("UpdateRouteIntlStatus", SqlEventTypes.Select,
                            new Dictionary<string, object>()
                            {
                                {"@strRouteIds", valId.ToString()},
                                {"@createdby", request.USERID},
                                {"@nStatus", mstas[i] == "Active" ? 0 : 1},
                                {"@CurrentStatus", request.CurrentStatus},

                                {"@ReturnValue", DBNull.Value},
                                {"@UserIp",request.UserIp}
                            });
                        if (request.CurrentStatus == 1)
                        {
                            AdminNotificationCallOne("Route");
                            AdminNotificationCallOne("Client");
                        }
                        if (res.Result.ReturnValue == -2)
                        {

                            failedIds.Add(res.Result.ReturnValue.ToString());
                            return failedIds;
                        }
                        if (res.Result.ReturnValue == 4)
                        {
                            failedIds.Add(valId);
                        }
                        i++;
                    }
                    return failedIds;
                }
            }
            catch (Exception ex)
            {
                Logger.InfoFormat("ChangeStatusUserRoute :: End :: Update UserRoute :: {0} ", request.ROUTEIDS, ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return null;
        }

