        /// <summary>
        /// Method Name : InsertRouteUserRoute
        /// Created By : 
        /// /// Created On : 
        /// Purpose : To Save or Update Route
        /// Modified By : 
        /// Modified On :
        /// Details of Modification :  
        /// </summary>  
        public async Task<int> InsertRouteUserRoute(InsertRouteUserRouteOnRequest request)
        {
            Logger.InfoFormat("InsertRouteUserRoute :: Started :: {0}", request.ROUTEID);
            try
            {
                using (var _consumer = new CoreDBConsumer())
                {
                    if (request.ROUTEID == 0)
                    {
                        var res = await
                            _consumer.DbConsumer<ReUsableResponse>("SetIntlRoutes", SqlEventTypes.Select,
                                new Dictionary<string, object>()
                                {
                                    {"@RouteName", request.ROUTENAME},
                                    {"@OperatorCountry", request.COUNTRYCODE},
                                    {"@NSmscId", request.SMSCID},
                                    {"@Vendorid", request.VENDORID},
                                    {"@nDefault", request.DEFAULT},
                                    {"@nAddedby", request.ADDEDBY},
                                    {"@nstatus", request.STATUS},
                                    {"@Route", request.ROUTEID},
                                    {"@CurrentStatus", request.CurrentStatus},

                                    {"@ReturnValue", DBNull.Value},
                                    {"@UserIp",request.UserIp}
                                    //{"@strCountryName",request.COUNTRYNAME},
                                    //{"@nSeriesID",request.SERIESID},  
                                });
                        if (request.CurrentStatus == 1)
                        {
                            AdminNotificationCallOne("Route");
                            AdminNotificationCallOne("Client");
                        }
                        return res.ReturnValue;
                    }
                    else
                    {
                        var res = await
                            _consumer.DbConsumer<ReUsableResponse>("UpdateIntlRoutes", SqlEventTypes.Select,
                                new Dictionary<string, object>()
                                {
                                    {"@NID", request.ROUTEID},
                                    {"@RouteName", request.ROUTENAME},
                                    {"@HdnRouteName", request.OLDROUTENAME},
                                    {"@STRCOUNTRYID", request.COUNTRYCODE},
                                    {"@STROPERATORID", Convert.ToInt32(request.SERIESID)},
                                    {"@ISDEFAULT", request.DEFAULT},
                                    {"@NUPDATEDBY", request.ADDEDBY},
                                    {"@VendorId", request.VENDORID},
                                    {"@SMSCName", Convert.ToInt32(request.SMSCID)},
                                    {"@CurrentStatus", request.CurrentStatus},

                                    {"@ReturnValue", DBNull.Value},
                                    {"@UserIp",request.UserIp}
                                });
                        Logger.InfoFormat("InsertRouteUserRoute :: End :: InsertRoute :: {0} ", res.ReturnValue);
                        if (request.CurrentStatus == 1)
                        {
                            AdminNotificationCallOne("Route");
                            AdminNotificationCallOne("Client");
                        }
                        return res.ReturnValue;
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.InfoFormat("InsertRouteUserRoute :: Error :: {0} ", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return 0;
        }

