        // Update users functions

        public async Task<string> AddTestSMSCByUser(AddSMSRequest request)
        {
            Logger.InfoFormat("AddTestSMSCByUser :: Started :: {0}", request.CustomerID);
            try
            {


                using (var _consumer = new CoreDBConsumer())
                {
                    var response = await
                        _consumer.DbConsumer<ReUsableResponse>("SetTestSmsc", SqlEventTypes.Select,
                            new Dictionary<string, object>()
                            {
                                {"@QSMSID", request.QSMSID},
                                {"@nSenderID", request.nSenderID},
                                {"@nLangId", Convert.ToInt32(request.nLangId)},
                                {"@strMsg", request.strMsg},
                                {"@nCharCount", request.nCharCount},
                                {"@nCreditsUsed", request.nCreditsUsed},
                                {"@TotalCreditsReq", request.TotalCreditsReq},
                                {"@CustomerID", request.CustomerID},
                                {"@nDLR", request.nDLR},
                                {"@nAddedBy", request.nAddedBy},
                                {"@Sender", request.Sender},
                                {"@Module", request.Module ?? ""},
                                {"@Status", request.Status},
                                {"@Currentstatus", 1},
                                {"@strMobiles", request.strMobiles},
                                {"@nId", request.nId},
                                {"@ReturnValue", DBNull.Value},
                                {"@UserIp",request.UserIp}
                            });
                    if (System.Configuration.ConfigurationManager.AppSettings["IndianSynapse"] == "false" || System.Configuration.ConfigurationManager.AppSettings["IndianSynapse"] == "" || System.Configuration.ConfigurationManager.AppSettings["IndianSynapse"] == null)
                    {
                        if (response.nId > 0)
                        {
                            var tCounts = request.strMobiles.Split(',').Length;
                            if (tCounts == 0)
                            {
                                tCounts = 1;
                            }

                            var LangID = Convert.ToInt32(request.nLangId);
                            if (LangID == 2)
                                LangID = 8;
                            else
                            {
                                if (request.strMsg.Contains('@') || request.strMsg.Contains('{') ||
                                    request.strMsg.Contains('}'))
                                    LangID = 1;
                                else
                                    LangID = 1;
                            }

                            //var userid = 
                            var fileName = DateTime.Now.ToString("ddMMyyyyhhmmss") + response.nId;
                            var xmlContent = "<root iscustome='false' priority='5'><sendsms userid='" + request.nAddedBy +
                                             "' campainid='" + 0 + "' sender='" + WebUtility.HtmlEncode(request.Sender) +
                                             "' language='" + ((LangID)) + "' message='" +
                                             WebUtility.HtmlEncode(request.strMsg).Replace("\n", "&#10;") +
                                             "' mobile=''><mobile>" + request.strMobiles + "</mobile></sendsms></root>";
                            var fPath = Path.Combine(
                                (System.Configuration.ConfigurationManager.AppSettings["CampaintPath"] + "QuickSMS"),
                                fileName); // + ".xml");
                            if (!Directory.Exists(fPath))
                            {
                                Directory.CreateDirectory(fPath);
                            }
                            File.WriteAllText(Path.Combine(fPath, fileName + ".xml"), xmlContent);
                            var QMsg = "action=start&camp_id=" + response.nId + "&camp_type=0&dir_name=" + fileName +
                                       "&count=" + tCounts;
                            var Qresult = new CampaignQLog().PushMessageToQ(QMsg);
                        }
                    }
                    return response.ReturnValue + "$" + response.nId;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("AddTestSMSCByUser :: Error :: {0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return await Task.Run(() => "0$0");
        }



