        public async Task<Int32> AddPreferedByIdAsync(AddPreferedRouteReq request)
        {
            Logger.InfoFormat("AddPreferedByIdAsync :: Started :: {0} :: {1} :: {2}", request.NCUSTOMERID, request.NROUTEID, request.NUSERID);
            try
            {
                using (var dbConsumer = new CoreDBConsumer())
                {
                    var success = new List<int>();
                    var multiUsers = request.NUSERID.Split(',').ToList();
                    var multiroutes = request.strNROUTEID.Split(',');
                    var multicountries = request.STRCOUNTRYCODE.Split(',').ToList();
                    if (multiUsers.Count > 1)
                    {
                        multiUsers = multiUsers.Where(s => !string.IsNullOrWhiteSpace(s) && !s.Equals("0")).ToList();
                    }
                    if (multicountries.Count > 1)
                    {
                        multicountries = multicountries.Where(s => !string.IsNullOrWhiteSpace(s) && !s.Equals("0")).ToList();
                    }
                    foreach (var user in multiUsers)
                    {
                        request.NUSERID = user;
                        foreach (var country in multicountries)
                        {
                            request.STRCOUNTRYCODE = country;
                            foreach (var route in multiroutes)
                            {
                                request.NROUTEID = Convert.ToInt32(route.Split(new[] { "||" }, StringSplitOptions.None)[0]);
                                request.NSERIES = Convert.ToInt32(route.Split(new[] { "||" }, StringSplitOptions.None)[1]);
                                request.STRCOUNTRYCODE = (route.Split(new[] { "||" }, StringSplitOptions.None)[2]).ToString();
                                if (request.STRCOUNTRYCODE == country)
                                {
                                    var PreUsers = dbConsumer.DbConsumerForMultiItems<DataTable>("SetPreferedRoutes", SqlEventTypes.Insert, buildUpdateParams(request));
                                    Logger.InfoFormat("AddPreferedByIdAsync :: End :: Add Preferred :: {0} ", PreUsers.Id);

                                    //dt.Rows[0][0].ToString()
                                    if (PreUsers.Result != null)
                                        success.Add(Convert.ToInt32(PreUsers.Result[0].Rows[0][0].ToString()));

                                    if (request.CurrentStatus == 1)
                                    {
                                        AdminNotificationCallOne("Route");
                                        AdminNotificationCallOne("Client");
                                    }
                                }
                            }
                        }
                    }

                    //multiUsers.ForEach(f =>
                    //{
                    //    request.NUSERID = f;
                    //    multicountries.ForEach(c =>
                    //    {
                    //        request.STRCOUNTRYCODE = c;
                    //        foreach (var route in multiroutes)
                    //        {                                
                    //            request.NROUTEID = Convert.ToInt32(route.Split(new[] { "||" }, StringSplitOptions.None)[0]);
                    //            request.NSERIES = Convert.ToInt32(route.Split(new[] { "||" }, StringSplitOptions.None)[1]);
                    //            request.STRCOUNTRYCODE = (route.Split(new[] { "||" }, StringSplitOptions.None)[2]).ToString();
                    //            if (request.STRCOUNTRYCODE == c)
                    //            {
                    //                var PreUsers = dbConsumer.DbConsumerForMultiItems<DataTable>("SetPreferedRoutes", SqlEventTypes.Insert, buildUpdateParams(request));
                    //                Logger.InfoFormat("AddPreferedByIdAsync :: End :: Add Preferred :: {0} ", PreUsers.Id);

                    //                //dt.Rows[0][0].ToString()
                    //                if (PreUsers.Result != null)
                    //                    success.Add(Convert.ToInt32(PreUsers.Result[0].Rows[0][0].ToString()));

                    //                if (request.CurrentStatus == 1)
                    //                {
                    //                    AdminNotificationCallOne("Route");
                    //                    AdminNotificationCallOne("Client");
                    //                }
                    //            }
                    //        }
                    //    });
                    //});
                    if (success.Any(a => a == 1))
                        return 1;
                    if (success.Any(a => a == 2))
                        return 2;
                    if (success.Any(a => a == 5))
                        return 5;
                    if (success.Any(a => a == 6))
                        return 6;
                    if (success.Any(a => a == 9))
                        return 9;

                    return 0;
                }
            }
            catch (Exception ex)
            {
                var error = ex.Message;
                Logger.ErrorFormat("AddPreferedByIdAsync :: {0} :: Error :: {1}", request.NCUSTOMERID, request.NROUTEID,
                    request.NUSERID, ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return 0;
        }

        private Dictionary<string, object> buildUpdateParams(AddPreferedRouteReq request)
        {
            Logger.InfoFormat("buildUpdateParams :: Started :: {0}", request.Id);

            var buildParams = new Dictionary<string, object>();
            try
            {
                switch (request.command)
                {
                    case "Add":
                        request.EventType = 1;
                        break;
                    case "Save":
                        request.EventType = 2;
                        break;
                    case "Pending":
                        request.EventType = 3;
                        break;
                    case "Reject":
                        request.EventType = 4;
                        break;
                }

                buildParams = new Dictionary<string, object>
                {
                    {"@Id", request.Id},
                    {"@NROUTEID", request.NROUTEID},
                    {"@NCUSTOMERID", request.NCUSTOMERID},
                    {"@NUSERID", Convert.ToInt32(request.NUSERID)},
                    {"@STRCOUNTRYCODE", request.STRCOUNTRYCODE},
                    {"@NSERIES", request.NSERIES},
                    {"@NCREATEDBY", request.NCREATEDBY},
                    {"@UPDATEDBY", request.UPDATEDBY},
                    {"@CurrentStatus", request.CurrentStatus},
                    {"@EVENTTYPE", request.command.Equals("Add", StringComparison.OrdinalIgnoreCase) ? "1" : "2"},

                    {"@ReturnValue", DBNull.Value},
                    {"@UserIp",request.UserIp}
                };
                return buildParams;
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal Error :: buildUpdateParams :: {0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return buildParams;
        }

