                using (var dbConsumer = new CoreDBConsumer())
                {
                    var Prefered = await dbConsumer.DbConsumer<Int32>("ApproveRejectPreferedRoute", SqlEventTypes.Update,
                    new Dictionary<string, object>
                    {
                    {"@Id", request.Id},
                    {"@Currentstatus", request.Currentstatus},
                    {"@Updatedby",request.Updatedby},
                    {"@rejectnote",request.Rejectnote ?? ""},
                    {"@Returnvalue",DBNull.Value}
                    });
                    Logger.InfoFormat("CheckerPreferedRouteUser :: End :: checkerPreferredRoute :: {0} ", Prefered);

                    if (string.IsNullOrWhiteSpace(request.Rejectnote))
                    {
                        if (request.Currentstatus == 1)
