                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return 0;
        }

        public List<string> ChangeStatus(PreferedStatus request)
        {
            Logger.InfoFormat("ChangeStatus :: Started :: {0}", request.CustomerId);
            var failedIds = new List<string>();
            try
            {
                using (var dbConsumer = new CoreDBConsumer())
                {
                    var Ids = request.CustomerId.Split(',').Where(w => !string.IsNullOrWhiteSpace(w)).ToList();
                    var mstas = request.chgstatus.Split(',');

                    int i = 0;
                    foreach (var valId in Ids)
                    {
                        var res = dbConsumer.DbConsumer<ReUsableResponse>("UpdatePreferedStatus", SqlEventTypes.Select,
                            new Dictionary<string, object>()
                            {
                                {"@CustomerId", valId.ToString()},
                                {"@createdby", request.createdby},
                                {"@Status", mstas[i] == "Active" ? 0 : 1},

                                {"@ReturnValue", DBNull.Value},
                                {"@UserIp",request.UserIp}
                            });
                        if (res.Result.ReturnValue == 5)
                        {
                            failedIds.Add(valId);
                        }
                        i++;
                    };
                    return failedIds;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("ChangeStatus :: {0} :: Error :: {1}", request.CustomerId, ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return null;
        }

