        public async Task<string> UpdateSMSCSwitchOverasync(SMSCSwithRequest request)
        {
            Logger.InfoFormat("UpdateSMSCSwitchOverasync :: Started :: {0}", request.FromSMSC);
            try
            {
                var result = new List<KeyValuePair<string, string>>();
                using (var _consumer = new CoreDBConsumer())
                {
                    var response = new ReUsableResponse();
                    var splitroutes = request.Routes.Split(',');
                    foreach (var sr in splitroutes)
                    {
                        response =
                            _consumer.DbConsumer<ReUsableResponse>("UpdateSwitchOverSMSC", SqlEventTypes.Select,
                                new Dictionary<string, object>()
                            {
                                {"@SwitchFromSMSCId", request.FromSMSC},
                                {"@SwithchToSMSCId", request.ToSMSC},
                                //{"@CountryCode", Convert.ToInt32(request.CountryCode)},
                                {"@MapSenderIds", request.Sender},
                                {"@UserIds",request.UserId},
                                {"@ToSMSCRouteIds", sr},
                                {"@UpdatedByUserId", request.CreatedBy},
                                {"@ReturnValue", DBNull.Value},
                                {"@UserIp",request.UserIp}
                            }).Result;
                        var keypair = new KeyValuePair<string, string>(sr,
                               response.ReturnValue.ToString());
                        result.Add(keypair);
                    }
                    //return Convert.ToString(response.ReturnValue);
                    var res = string.Empty;
                    foreach (var mo in result)
                    {
                        if (mo.Value == "1")
                        {
                            res += "IsValid=true:Message=Information Saved Successfully:" + mo.Key + "|-|";
                        }
                        if (mo.Value == "2")
                        {
                            res += "IsValid=false:Message=Route not found with the series on ToSMSC:" + mo.Key + "|-|";
                        }
                        if (mo.Value == "3")
                        {
                            res += "IsValid=false:Message=MappedRoutes Not exists on FromSMSC:" + mo.Key + "|-|";
                        }
                        if (mo.Value == "4")
                        {
                            res += "IsValid=false:Message=SenderIds not found:" + mo.Key + "|-|";
                        }
                        if (mo.Value == "")
                        {
                            res += "IsValid=false:Message=:" + mo.Key + "|-|";
                        }
                    }
                    return res;

                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("UpdateSMSCSwitchOverasync :: {0} :: Error :: {1}", request.FromSMSC, ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return null;
        }
