        public async Task<int> SaveCustomerCredits(SaveCustomerCreditsOnRequest request)
        {
            Logger.InfoFormat("SaveCustomerCredits :: Started :: {0}", request.CustomerCreditId);
            try
            {
                using (var _consumerDb = new CoreDBConsumer())
                {
                    if (request.CustomerCreditId > 0)
                        request.EventType = SqlEventTypes.Update;
                    else
                        request.EventType = SqlEventTypes.Insert;

                    if (request.EventType == SqlEventTypes.Insert)
                    {
                        var result = await
                            _consumerDb.DbConsumer<ReUsableResponse>("SetCustomerCredits",
                                SqlEventTypes.Select,
                                new Dictionary<string, object>()
                                {
                                    {"@NCUSTID", request.CustomerId},
                                    {"@NTRANSACTIONTYPE", request.TransactionType},
                                    {"@NCREATEDBY", request.CreatedBy},
                                    {"@NTRANCREDITS", request.TopUpCredits},
                                    {"@NCurrentStatus", request.FStatus},
                                    {"@NCREDITTYPE", request.CreditType},
                                    {"@STRREMARKS", request.Remarks},
                                    {"@ReturnValue", 0},
                                    {"@UserIp",request.UserIp},
                                    {"@THRESHOLDLIMIT",request.ThresholdLimit},
                                    {"@AutoResetCredits",request.AutoResetCredits}
                                });
                        if (request.FStatus == 1)
                        {
                            AdminNotificationCallOne("Route");
                        }
                        return result.NRETVAL = result.ReturnValue;
                    }
                    else //if(request.EventType==SqlEventTypes.Update)
                    {
                        var result = await
                            _consumerDb.DbConsumer<ReUsableResponse>("UpdateCustomerCredits",
                                SqlEventTypes.Select,
                                new Dictionary<string, object>()
                                {
                                    {"@NCUSTID", request.CustomerId},
                                    {"@NTRANSACTIONTYPE", request.TransactionType},
                                    {"@NDETCREDITSID", request.CustomerCreditId},
                                    {"@NCREATEDBY", request.CreatedBy},
                                    {"@NTRANCREDITS", request.TopUpCredits},
                                    {"@STRREMARKS", request.Remarks},
                                    {"@CREDITTYPE", request.CreditType},
                                    {"@ReturnValue", 0},
                                    {"@UserIp",request.UserIp}
                                });
                        if (request.FStatus == 1)
                        {
                            AdminNotificationCallOne("Route");
                        }
                        return result.NRETVAL = result.ReturnValue;
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal Error SaveCustomerCredits :: {0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return 0;
        }


