        /// <summary>
        /// Method Name : InsertSMPPIPAllocation
        /// Created By : 
        /// Created On : 
        /// Purpose : To Save IP details for selected user and Approve or Reject IP details of selected
        /// Modified By : 
        /// Modified On :
        /// Details of Modification :  
        /// </summary>
        public async Task<int> InsertSMPPIPAllocation(SetSmppIPAllocationOnRequest request)
        {
            Logger.InfoFormat("InsertSMPPIPAllocation :: Started :: {0} :: {1}", request.CustomerID, request.USERID);
            List<int> response = new List<int>();
            try
            {
                using (var _consumer = new CoreDBConsumer())
                {
                    if (request.InsertCheckerFlag == 1)
                    {
                        if (request.SMPPIPS.Count > 0)
                        {
                            request.SMPPIPS.ForEach(x =>
                            {
                                var res = _consumer.DbConsumer<ReUsableResponse>("SetSMPPIpWhiteList",
                                    SqlEventTypes.Select,
                                    new Dictionary<string, object>()
                                    {
                                        {"@CustomerID", x.CustomerID},
                                        {"@USERID", x.USERID},
                                        {"@IPADDRESS", x.IPAddress},
                                        {"@NOOFSESSIONS", x.NoOfSession},
                                        {"@NSMPPID", x.SMPPID},
                                        {"@Status", x.Status},
                                        {"@CurrentStatus", x.CurrentStatus},
                                        {"@ReturnValue", DBNull.Value},
                                        {"@UserIp",request.UserIp}
                                    });
                                if (x.CurrentStatus == 1)
                                {
                                    AdminNotificationCallOne("Server");
                                }
                                response.Add(res.Result.ReturnValue);
                            });
                        }
                    }
                    else if (request.InsertCheckerFlag == 2)
                    {
                        request.SMPPIPS.ForEach(x =>
                        {
                            var res = _consumer.DbConsumer<ReUsableResponse>("ApproveOrRejectSMPPIP",
                                SqlEventTypes.Select,
                                new Dictionary<string, object>()
                                {
                                    {"@ID", x.AutoID},
                                    {"@UpdatedBy", x.UpdatedBy},
                                    {"@CurrentStatus", x.CurrentStatus},
                                    {"@Rejectreason", x.RejectReason},
                                    {"@ReturnValue", DBNull.Value}
                                });
                            if (string.IsNullOrWhiteSpace(x.RejectReason))
                            {
                                if (x.CurrentStatus == 1)
                                {
                                    AdminNotificationCallOne("Server");
                                }
                            }
                            response.Add(res.Result.ReturnValue);
                        });
                    }
                    if (response.Contains(7))
                    {
                        return 7;
                    }
                    else if (response.Contains(2))
                    {
                        return 2;
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal Error InsertSMPPIPAllocation :: {0}", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return 0;
        }

