                                    {"@Instance", request.Instance ?? ""},
                                     {"@AssembleLongMessages", request.AssembleLongMessages},
                                    {"@CurrentStatus", request.CurrentStatus},
                                    {"@ReturnValue", DBNull.Value},
                                    {"@UserIp",request.UserIp}
                                });
                        Logger.InfoFormat(
                            "InsertSMPPMaster :: End :: InsertSMPPMaster :: CustomerId {0} & SMPPUSERID {1} ",
                            request.CustomerID, request.SMPPUSERID);
                        if (request.CurrentStatus == 1)
                        {
                            AdminNotificationCallOne("Server");
