        public int TestConnections(TestConnectionOnRequest Request)
        {
            Logger.Info("Test connection execution :: entered into Core.Data");
            int returnVal = 0;
            string strConnection = "";
            Logger.InfoFormat("Test connection execution start Core.Data :: ServerName:: {0} & UserName:: {1} & Port :: {2} & Type :: {3} & DBname :: {4} & UserType :: {5} ",
                AppInternalEncKey.Encrypt(Request.strservername, false),
                AppInternalEncKey.Encrypt(Request.strusername, false),
                AppInternalEncKey.Encrypt(Request.strport, false), AppInternalEncKey.Encrypt(Request.strtype, false),
                AppInternalEncKey.Encrypt(Request.strdbname, false), AppInternalEncKey.Encrypt(Request.struserType, false));
            try
            {
                strConnection = GetConnString(AppInternalEncKey.Decrypt(Request.strservername, false), AppInternalEncKey.Decrypt(Request.strusername, false), AppInternalEncKey.Decrypt(Request.strpassword, false), AppInternalEncKey.Decrypt(Request.strport, false), AppInternalEncKey.Decrypt(Request.strtype, false), AppInternalEncKey.Decrypt(Request.strdbname, false), strConnection, Request.ConnectType);
                Logger.Info("Connection :: " + AppInternalEncKey.Encrypt(strConnection, false));
                if (AppInternalEncKey.Decrypt(Request.strtype, false) == "1")//sql 
                {
                    Logger.Info("SqlConnectlion Started");
                    using (SqlConnection con = new SqlConnection(strConnection))
                    {
                        con.Open();
                        Logger.Info("SQL Connection Succeseded");
                        returnVal = 1;
                    }
                    return returnVal;
                }
                else if (AppInternalEncKey.Decrypt(Request.strtype, false) == "2")//oracle
                {
                    //strConnection = "Data Source = (DESCRIPTION=(ADDRESS=(PROTOCOL=TCP)(HOST=" +Request.strservername + ")(PORT=" + Request.strport + "))(CONNECT_DATA=(SERVICE_NAME=" + Request.strdbname + ")));user id=" + Request.strusername + ";password=" +Request.strpassword + ";";
                    Request.strservername = AppInternalEncKey.Decrypt(Request.strservername, false);
                    Request.strport = AppInternalEncKey.Decrypt(Request.strport, false);
                    Request.strdbname = AppInternalEncKey.Decrypt(Request.strdbname, false);
                    Request.strusername = AppInternalEncKey.Decrypt(Request.strusername, false);
                    Request.strpassword = AppInternalEncKey.Decrypt(Request.strpassword, false);



                    // strConnection = "Data Source = (DESCRIPTION=(ADDRESS=(PROTOCOL=TCP)(HOST=" + Request.strservername + ")(PORT=" + Request.strport + "))(CONNECT_DATA=(SERVICE_NAME=" + Request.strdbname + ")));user id=" + Request.strusername + ";password=" + Request.strpassword + ";";
                    Logger.InfoFormat("Oracle Client Connection starts");
                    var ClientCon = System.Configuration.ConfigurationManager.AppSettings["OracleClientCon"];
                    Logger.InfoFormat("Oracle Client Connection is - {0}", AppInternalEncKey.Encrypt(ClientCon, false));
                    // strConnection = "Data Source = (DESCRIPTION=(ADDRESS=(PROTOCOL=TCP)(HOST=" + Request.strservername + ")(PORT=" + Request.strport + "))(CONNECT_DATA=(SERVICE_NAME=" + Request.strdbname + ")));user id=" + Request.strusername + ";password=" + Request.strpassword + ";";
                    Logger.InfoFormat("Oracle Client Dynamic Connection starts");
                    strConnection = ClientCon.Replace("$strservername$", Request.strservername).Replace("$strport$", Request.strport).Replace("$strdbname$", Request.strdbname).Replace("$strusername$", Request.strusername).Replace("$strpassword$", Request.strpassword);
                    Logger.InfoFormat("Oracle Client Dynamic Connection is - {0} ", AppInternalEncKey.Encrypt(strConnection, false));
                    //strConnection = (System.Configuration.ConfigurationManager.AppSettings["IsServiceNameorSID"] == "SID") ? strConnection.Replace("$SERVICE_NAME$", "SID") : strConnection.Replace("$SERVICE_NAME$", "SERVICE_NAME");
                    if (Request.ConnectType == 1)
                    {
                        strConnection = strConnection.Replace("$SERVICE_NAME$", "SERVICE_NAME");
                    }
                    else
                    {
                        strConnection = strConnection.Replace("$SERVICE_NAME$", "SID");
                    }
                    Logger.InfoFormat("Is ServiceName or SID - {0} ", AppInternalEncKey.Encrypt(strConnection, false));
                    using (OracleConnection conn = new OracleConnection(strConnection))
                    {
                        Logger.Info("Connection Open Start");
                        if (conn == null)
                        {
                            Logger.Info("Connection Object NULL");
                        }
                        else
                        {
                            try
                            {
                                conn.Open();
                                Logger.Info("Oracle Connection Succeseded");
                                returnVal = 1;
                            }
                            catch (OracleException oex)
                            {
                                Logger.ErrorFormat("Connection Error :: {0} & stacktrace :: {1}", oex.ToString(), oex.StackTrace);
                                Logger.ErrorFormat("Connection Error Source :: {0}", oex.Source);
                                if (oex.Message.Contains("System.Data.OracleClient"))
                                {
                                    Logger.InfoFormat("Profile - Connection not established due to : {0}", oex.Message);
                                    return 33;
                                }
                                if (oex.Message.Contains("No such host is known")) //error in host for sql
                                {
                                    Logger.InfoFormat("Profile - Connection not established due to : {0}", oex.Message);
                                    return 44;
                                }
                                if (oex.Message.Contains("The wait operation timed out"))  //error in port for sql
                                {
                                    Logger.InfoFormat("Profile - Connection not established due to : {0}", oex.Message);
                                    return 11;
                                }

                                if (oex.Message.Contains("Login failed for user")) //not correct user and password
                                {
                                    Logger.InfoFormat("Profile - Connection not established due to : {0}", oex.Message);
                                    return 22;
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                // Logger.ErrorFormat("Full Exception Details ::  {0}", ex.StackTrace);
                Logger.ErrorFormat("Full Exception Details ::  {0} & Error :: {1}", ex.StackTrace, ex.ToString());
                if (ex.Message.Contains("System.Data.OracleClient"))
                {
                    returnVal = 33;

                    Logger.InfoFormat("Profile - Connection not established due to : {0}", ex.Message);
                    return returnVal;
                }

                if (ex.Message.Contains("No such host is known")) //error in host for sql
                {
                    returnVal = 44;

                    Logger.InfoFormat("Profile - Connection not established due to : {0}", ex.Message);
                    return returnVal;
                }

                if (ex.Message.Contains("The wait operation timed out"))  //error in port for sql
                {
                    returnVal = 11;

                    Logger.InfoFormat("Profile - Connection not established due to : {0}", ex.Message);
                    return returnVal;
                }

                if (ex.Message.Contains("Login failed for user")) //not correct user and password
                {
                    returnVal = 22;

                    Logger.InfoFormat("Profile - Connection not established due to : {0}", ex.Message);
                    return returnVal;
                }

                Logger.InfoFormat("Profile - Connection not established : {0}", ex.Message);

                return returnVal;
            }

            return returnVal;
        }

        private string GetConnString(string servername, string username, string password, string port, string type, string dbname, string strConnection, int ConnectType)
        {

            try
            {
                if (type == "1") //sql
                {
                    if (dbname == "" || dbname == "0")
                    {
                        strConnection = "Data Source=" + servername + "," + port + ";Initial Catalog=master;User ID=" + username + ";Password=" + password;
                    }
                    else
                    {

                        strConnection = "Data Source=" + servername + "," + port + ";Initial Catalog=" + dbname + ";User ID=" + username + ";Password=" + password;
                    }
                }
                else if (type == "2")//oracle
                {
                    // strConnection = "Data Source=(DESCRIPTION=(ADDRESS_LIST=(ADDRESS=(PROTOCOL=TCP)(HOST=192.168.7.168)(PORT=1521)))(CONNECT_DATA=(SERVER=DEDICATED)(SERVICE_NAME=XE)));User Id=system;Password=123;";
                    //  strConnection = "Data Source=(DESCRIPTION=(ADDRESS_LIST=(ADDRESS=(PROTOCOL=TCP)(HOST=" + servername + ")(PORT=" + port + ")))(CONNECT_DATA=(SERVER=DEDICATED)(SERVICE_NAME=" + dbname + ")));User Id=" + username + ";Password=" + password + ";";
                    if (ConnectType == 1)
                    {
                        //strConnection = "Data Source=(DESCRIPTION=(ADDRESS_LIST=(ADDRESS=(PROTOCOL=TCP)(HOST=" + servername + ")(PORT=" + port + ")))(CONNECT_DATA=(SERVER=DEDICATED)(" + (System.Configuration.ConfigurationManager.AppSettings["IsServiceNameorSID"] == "SID" ? "SID=" + dbname : "SERVICE_NAME=" + dbname) + ")));User Id=" + username + ";Password=" + password + ";";
                        strConnection = "Data Source=(DESCRIPTION=(ADDRESS_LIST=(ADDRESS=(PROTOCOL=TCP)(HOST=" + servername + ")(PORT=" + port + ")))(CONNECT_DATA=(SERVER=DEDICATED)(SERVICE_NAME=" + dbname + ")));User Id=" + username + ";Password=" + password + ";";

                    }
                    else
                    {
                        strConnection = "Data Source=(DESCRIPTION=(ADDRESS_LIST=(ADDRESS=(PROTOCOL=TCP)(HOST=" + servername + ")(PORT=" + port + ")))(CONNECT_DATA=(SERVER=DEDICATED)(SID=" + dbname + ")));User Id=" + username + ";Password=" + password + ";";
                    }
                    // strConnection = "Data Source=" + servername + ";User ID=" + username + ";Password=" + password;
                    //strConnection = "Data Source=XE;User Id=oracle1;Password=123;";
                }
                return strConnection;
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Full Exception Details ::  {0} & Error :: {1}", ex.StackTrace, AppInternalEncKey.Encrypt(strConnection, false));
            }
            return strConnection;
        }


        public List<DefaultDBsOnResponse> Getdefultdbs(TestConnectionOnRequest Request)
        {
            string strConnection = "";
            strConnection = GetConnString(AppInternalEncKey.Decrypt(Request.strservername, false), AppInternalEncKey.Decrypt(Request.strusername, false), AppInternalEncKey.Decrypt(Request.strpassword, false), AppInternalEncKey.Decrypt(Request.strport, false), AppInternalEncKey.Decrypt(Request.strtype, false), AppInternalEncKey.Decrypt(Request.strdbname, false), strConnection, Request.ConnectType);

            if (AppInternalEncKey.Decrypt(Request.strtype, false) == "1") //sql
            {
                using (SqlConnection con = new SqlConnection(strConnection))
                {
                    con.Open();
                    SqlCommand cmd = new SqlCommand("SELECT [NAME] as DBName FROM SYS.DATABASES ORDER BY DBName");
                    cmd.Connection = con;
                    SqlDataAdapter da = new SqlDataAdapter(cmd);
                    DataSet ds = new DataSet();
                    da.Fill(ds);
                    if (ds.Tables[0].Rows.Count > 0)
                    {
                        var myData = ds.Tables[0].AsEnumerable().Select(r => new DefaultDBsOnResponse
                        {
                            DBName = r.Field<string>("DBName")

                        });
                        return myData.ToList();
                    }

                }
                //return new List<DefaultDBsOnResponse>();
            }
            else if (AppInternalEncKey.Decrypt(Request.strtype, false) == "2") //oracle
            {
                using (OracleConnection orcconn = new OracleConnection(strConnection))
                {
                    orcconn.Open();
                    OracleCommand orccmd = new OracleCommand("select Username as DBName from DBA_USERS ORDER BY DBName");
                    orccmd.Connection = orcconn;
                    OracleDataAdapter orcda = new OracleDataAdapter(orccmd);
                    DataSet orcds = new DataSet();
                    orcda.Fill(orcds);
                    if (orcds.Tables[0].Rows.Count > 0)
                    {
                        var myDataOrc = orcds.Tables[0].AsEnumerable().Select(r => new DefaultDBsOnResponse
                        {
                            DBName = r.Field<string>("DBName")

                        });
                        return myDataOrc.ToList();
                    }
                }
            }
            return new List<DefaultDBsOnResponse>();
        }


