        public async Task<TestStatementViewOnResponse> TestStatementView(TestStatementOnRequest Request)
        {
            Logger.InfoFormat("TestStatementView Excecution started{0}", Request);
            String daresult = null;
            TestStatementViewOnResponse Resulttab = new TestStatementViewOnResponse();
            try
            {
                //Commented for To fix warning :: The variable 'columnNames' is assigned but its value is never used on 12Dec2019
                //string[] columnNames = null;
                if (Request.Dbtype == 1) //sql
                {
                    using (SqlConnection con = new SqlConnection(Request.Connection))
                    {
                        var sqlstatement = HttpUtility.UrlDecode(Request.Statement.Trim());
                        con.Open();
                        SqlCommand cmd = new SqlCommand(sqlstatement);
                        Logger.InfoFormat("SQL Statement :: {0}", AppInternalEncKey.Encrypt(sqlstatement, false));
                        cmd.Connection = con;
                        SqlDataAdapter da = new SqlDataAdapter(cmd);
                        DataSet ds = new DataSet();
                        da.Fill(ds);

                        daresult = DataTableToJSON(ds.Tables[0]);
                        Resulttab.ResultTable = daresult;
                        Resulttab.Result = "1";
                        Resulttab.ResultError = "Success";
                        return Resulttab;
                    }
                    //return new List<DefaultDBsOnResponse>();
                }
                else if (Request.Dbtype == 2) //oracle
                {
                    //  Request.Connection = "Data Source=(DESCRIPTION=(ADDRESS_LIST=(ADDRESS=(PROTOCOL=TCP)(HOST=192.168.7.50)(PORT=1521)))(CONNECT_DATA=(SERVER=DEDICATED)(SERVICE_NAME=vmtest)));User Id=scott;Password=tiger;";
                    using (OracleConnection orcconn = new OracleConnection(Request.Connection))
                    {
                        Logger.Info("Connection Open Start");
                        try
                        {
                            if (orcconn == null)
                            {
                                Logger.Info("Oracle Connection NULL");
                            }
                            else
                            {
                                orcconn.Open();
                                var statement = HttpUtility.UrlDecode(Request.Statement.Trim());
                                Logger.InfoFormat("ORA Statement :: {0}", AppInternalEncKey.Encrypt(statement, false));
                                OracleCommand orccmd = new OracleCommand(statement);
                                orccmd.Connection = orcconn;
                                orccmd.CommandText = orccmd.CommandText.Replace(";", "");
                                OracleDataAdapter orcda = new OracleDataAdapter(orccmd);
                                DataSet orcds = new DataSet();
                                orcda.Fill(orcds);
                                daresult = DataTableToJSON(orcds.Tables[0]);
                                Resulttab.ResultTable = daresult;
                                Resulttab.Result = "1";
                                Resulttab.ResultError = "Success";
                                Logger.InfoFormat("Data Adopter Result :: {0}", AppInternalEncKey.Encrypt(daresult, false));
                                return Resulttab;
                            }
                        }
                        catch (OracleException oex)
                        {
                            Resulttab.Result = "0";
                            Resulttab.ResultError = oex.Message;
                            Logger.ErrorFormat("Oracle Error :: {0} & stacktrace {1}", oex.ToString(), oex.StackTrace);
                            Logger.ErrorFormat("Oracle Source :: {0}", oex.Source);
                            return Resulttab;
                        }
                    }
                }
            }
            catch (Exception E)
            {
                Resulttab.Result = "0";
                Resulttab.ResultError = E.Message;

                Logger.ErrorFormat("Full Exception Details ::  {0} & Error :: {1}", E.StackTrace, E.ToString());

                return Resulttab;
            }
            Logger.InfoFormat("TestStatementView Excecution end{0}", Request);
            return new TestStatementViewOnResponse();
        }

        private static string DataTableToJSON(DataTable Dt)
        {
            string[] StrDc = new string[Dt.Columns.Count];
            int DtCount = Dt.Rows.Count;
            string HeadStr = string.Empty;
            for (int i = 0; i < Dt.Columns.Count; i++)
            {

                StrDc[i] = Dt.Columns[i].Caption;
                if (DtCount == 0)
                {
                    HeadStr += "\"" + StrDc[i] + "\":\"" + "#VMSYN#" + "\",";
                }
                else
                {
                    HeadStr += "\"" + StrDc[i] + "\":\"" + StrDc[i] + i.ToString() + "¾" + "\",";
                }


            }

            HeadStr = HeadStr.Substring(0, HeadStr.Length - 1);

            System.Text.StringBuilder Sb = new System.Text.StringBuilder();

            Sb.Append("[");

            for (int i = 0; i < Dt.Rows.Count; i++)
            {
                if (i >= 5)
                    break;
                string TempStr = HeadStr;

                for (int j = 0; j < Dt.Columns.Count; j++)
                {

                    TempStr = TempStr.Replace(Dt.Columns[j] + j.ToString() + "¾", Dt.Rows[i][j].ToString().Replace("'", "^").Replace("\"", "^^").Trim());
                }
                //Sb.AppendFormat("{{{0}}},",TempStr);

                Sb.Append("{" + TempStr + "},");
            }
            if (DtCount == 0)
            {
                Sb.Append("{" + HeadStr + "},");
            }
            Sb = new System.Text.StringBuilder(Sb.ToString().Substring(0, Sb.ToString().Length - 1));

            if (Sb.ToString().Length > 0)
                Sb.Append("]");

            return StripControlChars(Sb.ToString());

        }
        //To strip control characters:

        //A character that does not represent a printable character but //serves to initiate a particular action.
        private static string StripControlChars(string s)
        {
            return System.Text.RegularExpressions.Regex.Replace(s, @"[^\x20-\x7F]/u", "");
        }

        public async Task<string[]> TestStatement(TestStatementOnRequest Request)
        {
            Logger.InfoFormat("TestStatement Excecution started", Request);
            string[] Result = new string[2];
            try
            {

                string[] columnNames = null;
                if (Request.Dbtype == 1) //sql
                {
                    using (SqlConnection con = new SqlConnection(Request.Connection))
                    {
                        var sqlstatement = HttpUtility.UrlDecode(Request.Statement.Trim());
                        //if (!string.IsNullOrWhiteSpace(sqlstatement))
                        //{
                        //    var fromcount = sqlstatement.ToLower().StringBetween("select", "from");
                        //    var SelectedColumns = fromcount[0]+","+ Request.un;
                        //    if (fromcount.Count() > 1)
                        //    {
                        //        var ArrayItems = sqlstatement.StringBetween("select", "from");
                        //    }
                        //    else
                        //    {
                        //        var StatementResultArray = sqlstatement.Between("select", "from");
                        //    }
                        //}
                        con.Open();
                        SqlCommand cmd = new SqlCommand(sqlstatement);
                        Logger.InfoFormat("SQL Statement Save :: {0}", AppInternalEncKey.Encrypt(sqlstatement, false));
                        cmd.Connection = con;
                        SqlDataAdapter da = new SqlDataAdapter(cmd);
                        DataSet ds = new DataSet();
                        da.Fill(ds);

                        columnNames = ds.Tables[0].Columns.Cast<DataColumn>()
                                    .Select(x => x.ColumnName)
                                    .ToArray();

                        //columnNames = ds.Tables[0].Rows.Count.ToArray();
                        //if (ds.Tables[0].Rows.Count > 0)
                        //{
                        //var myData = ds.Tables[0].AsEnumerable().Select(r => new DefaultDBsOnResponse
                        //{
                        //    DBName = r.Field<string>("DBName")

                        //});
                        DataTable dt = ds.Tables[0];
                        var dynamicDt = new List<dynamic>();
                        foreach (DataRow row in dt.Rows)
                        {
                            dynamic dyn = new System.Dynamic.ExpandoObject();
                            dynamicDt.Add(dyn);
                            foreach (DataColumn column in dt.Columns)
                            {
                                var dic = (IDictionary<string, object>)dyn;
                                dic[column.ColumnName] = row[column];
                            }
                        }

                        if (columnNames.Length == 0)
                        {
                            Result[0] = "0";
                            Result[1] = "Failed";
                            return Result;
                        }
                        else
                        {
                            var tablecolumn = "";
                            for (int i = 0; i < columnNames.Length; i++)
                            {
                                if (tablecolumn == "")
                                {
                                    tablecolumn = columnNames[i].ToString();
                                }
                                else
                                {
                                    tablecolumn = tablecolumn + "," + columnNames[i].ToString();
                                }

                            }
                            Result[0] = "1";
                            Result[1] = tablecolumn;
                            return Result;
                        }

                        // }

                    }
                    //return new List<DefaultDBsOnResponse>();
                }
                else if (Request.Dbtype == 2) //oracle
                {
                    using (OracleConnection orcconn = new OracleConnection(Request.Connection))
                    {
                        orcconn.Open();
                        var statement = HttpUtility.UrlDecode(Request.Statement.Trim());
                        OracleCommand orccmd = new OracleCommand(statement);
                        Logger.InfoFormat("ORA Statement Save :: {0}", AppInternalEncKey.Encrypt(statement, false));
                        orccmd.Connection = orcconn;
                        orccmd.CommandText = orccmd.CommandText.Replace(";", "");
                        OracleDataAdapter orcda = new OracleDataAdapter(orccmd);
                        DataSet orcds = new DataSet();
                        orcda.Fill(orcds);
                        columnNames = orcds.Tables[0].Columns.Cast<DataColumn>()
                                    .Select(x => x.ColumnName)
                                    .ToArray();
                        //if (orcds.Tables[0].Rows.Count > 0)
                        //{
                        //    //var myDataOrc = orcds.Tables[0].AsEnumerable().Select(r => new DefaultDBsOnResponse
                        //    //{
                        //    //    DBName = r.Field<string>("DBName")

                        //    //});
                        if (columnNames.Length == 0)
                        {
                            Result[0] = "0";
                            Result[1] = "Failed";
                            return Result;
                        }
                        else
                        {
                            var tablecolumn = "";
                            for (int i = 0; i < columnNames.Length; i++)
                            {
                                if (tablecolumn == "")
                                {
                                    tablecolumn = columnNames[i].ToString();
                                }
                                else
                                {
                                    tablecolumn = tablecolumn + "," + columnNames[i].ToString();
                                }

                            }
                            Result[0] = "1";
                            Result[1] = tablecolumn;
                            return Result;
                        }
                        //}
                    }
                }
            }
            catch (Exception E)
            {
                Result[0] = "0";
                Result[1] = E.Message;
                Logger.ErrorFormat("Full Exception Details ::  {0} & Error :: {1}", E.StackTrace, E.ToString());
                return Result;
            }
            Logger.InfoFormat("TestStatement Excecution end", Request);
            return await Task.Run(() => Result);
        }

