                            {"@STRMESSAGEFLD",request.STRMESSAGEFIELD},
                            {"@STRPLACEHOLDERS",request.STRPLACEHOLDERS},
                            {"@NTEMPLATEID",request.NMESSAGETEMPLATEID},
                            {"@LANGUAGE",request.Language},
                            {"@STRMESSAGE",request.STRMESSAGE},
                            {"@NDLRREQUIRED",request.NDLRREQUIRED == true ? 1 : 0},
                            {"@SENDNOWORSCHEDULELATER",request.SendNowOrScheduleLater},
                            {"@INTERVALTYPE",request.IntervalType},
                            {"@INTERVALVALUE",request.IntervalValue},
                            //{"@BANKID",request.BankId},

                            {"@BANKID",request.CustomerId},
                            {"@EMAILFIELD",request.EmailField},
                            {"@EMAILTEMPID",request.EmailTemplateId},
                            {"@EMAILTEMPTEXT",request.EmailTemplateText},
                            {"@NUPDATEDBY",request.NUPDATEDBY},
                            {"@NRETURN",DBNull.Value},
                            {"@CURRENTSTATUS",request.CURRENTSTATUS},
                            {"@STATUS",request.STATUS},
                            {"@UserIp",request.UserIp}
                        });

                        if (res.ReturnValue == 1)
                        {
                            try
                            {

                                if (request.NCREATEDBY == 1)
                                {
                                    Logger.InfoFormat("UpdateAlertNotification STARTING from InsertOnlineCreation :: Started :: {0}", request.NCREATEDBY.ToString() + "," + request.NID.ToString() + "," + DateTime.Now.ToString());
                                    AlertManagerNotificationConsumption servRef = new AlertManagerNotificationConsumption();
                                    Logger.InfoFormat("UpdateAlertNotification ENDING from InsertOnlineCreation :: ENDED :: {0}", request.NCREATEDBY.ToString() + "," + request.NID.ToString() + "," + DateTime.Now.ToString());
                                    var alerRep = servRef.PushAlertNotif(request.UserId.ToString(), request.NID.ToString(), "update");
                                }
                            }
                            catch (Exception ex)
                            {
                                Logger.InfoFormat("ERROR: UpdateAlertNotification ERROR from InsertOnlineCreation :: ERROR :: {0}", request.NCREATEDBY.ToString() + "," + request.NID.ToString() + "," + DateTime.Now.ToString() + ", at" + ex.Message.ToString());
                            }
                        }
                        return res.ReturnValue;
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("InsertOnlineCreation :: Error :: {0}", ex.ToString());
            }
            return await Task.Run(() => 0);
        }

