        public async Task<int> ChangeOnlineAlertsStatus(ChangeOnlineAlertsStatusRequest request)
        {
            try
            {
                using (var _consumer = new CoreDBConsumer())
                {
                    var res = await _consumer.DbConsumer<ReUsableResponse>("UpdateOnlineAlertsStatus", SqlEventTypes.Select,
                        new Dictionary<string, object>(){
                    {"@NID",request.NID},
                    {"@NSTATUS",request.NSTATUS},
                    {"@NUPDATEDBY",request.NUPDATEDBY},
                    {"@NUPDATEDUSER",request.NUPDATEDUSER},
                    {"@CurrentStatus",request.CURRENTSTATUS},
                    {"@NRETURN",DBNull.Value},
                    {"@UserIp",request.UserIp}
                    });
                    string strActOrInac = "";
                    //ignore the currentstatus   
                    //if (request.NSTATUS == 1 && request.CURRENTSTATUS == 1)
                    if (request.NSTATUS == 1)
                    {
                        //strActOrInac = "Active";
                        strActOrInac = "add";
                    }
                    else
                    {
                        //strActOrInac = "Inactive";
                        strActOrInac = "stop";
                    }
                    //if (res.ReturnValue == 1 && request.CURRENTSTATUS == 1)
                    if (res.ReturnValue == 1)
                    {
                        try
                        {
                            if (request.NUPDATEDBY == 1)
                            {
                                Logger.InfoFormat("Change OnlineAlerts Status :: Started :: {0}  ", request.NID.ToString() + "," + DateTime.Now.ToString());
                                AlertManagerNotificationConsumption servRef = new AlertManagerNotificationConsumption();

                                var alerRep = servRef.PushAlertNotif(request.NUPDATEDBY.ToString(), request.NID.ToString(), strActOrInac);

                                Logger.InfoFormat("Change OnlineAlerts Status :: Ended :: {0}  ", request.NID.ToString() + "," + DateTime.Now.ToString());
                            }
                        }
                        catch (Exception ex)
                        {
                            Logger.InfoFormat("ERROR:Change OnlineAlerts Status ERROR from UpdateOnlineAlertsStatus :: ERROR :: {0}", request.NUPDATEDBY.ToString() + "," + request.NID.ToString() + "," + DateTime.Now.ToString() + ", at" + ex.Message.ToString());
                        }
                    }

                    return res.ReturnValue;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("ChangeOnlineAlertStatus :: Error :: {0}", ex.ToString());
            }
            return await Task.Run(() => 0);
        }

        public async Task<int> CheckerUpdateOnlineAlerts(ApproveRejectAlertsCreation request)
        {
            try
            {
                using (var _consumer = new CoreDBConsumer())
                {
                    var res = await _consumer.DbConsumer<ReUsableResponse>("ApproveOrRejectDBAlerts", SqlEventTypes.Select,
                        new Dictionary<string, object>(){
                {"@AlertId",request.ALERTId},
                {"@CURRENTSTATUS",request.CURRENTSTATUS},
                {"@UpdatedBy",request.UpdatedBy},
                {"@Rejectreason",(request.Rejectreason ?? "")=="" ? "" : request.Rejectreason.Trim()},
                {"@ReturnValue",DBNull.Value}
                });

                    string opType = "";
                    if (res.ReturnValue == 1)  //call stop notification
                    {
                        opType = "add";
                        res.ReturnValue = 1;

                    }

                    if (res.ReturnValue == 7)   //call stop notification
                    {
                        opType = "stop";
                        res.ReturnValue = 1;

                    }

                    if (res.ReturnValue == 9)
                    {
                        opType = "update";  //call stop notification
                        res.ReturnValue = 1;

                    }
                    if (request.CURRENTSTATUS == 1)
                    {
                        var alrtResp = "";
                        try
                        {
                            AlertManagerNotificationConsumption servRef = new AlertManagerNotificationConsumption();
                            //alrtResp = servRef.PushAlertNotif(request.UpdatedBy.ToString(), request.ALERTId.ToString(), opType);
                            alrtResp = servRef.PushAlertNotif(res.nId.ToString(), request.ALERTId.ToString(), opType);
                            Logger.InfoFormat("AddAlertNotification END from InsertOnlineCreation :: ENDED :: {0}", request.UpdatedBy.ToString() + "," + request.ALERTId.ToString() + ", at" + DateTime.Now.ToString());

                        }
                        catch (Exception ex)
                        {
                            Logger.InfoFormat("AddAlertNotification ERROR from InsertOnlineCreation :: ERROR :: {0}", request.UpdatedBy.ToString() + "," + request.ALERTId.ToString() + ", at" + ex.Message.ToString());
                        }
                    }
                    return res.ReturnValue;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("CheckerUpdateOnlineAlerts:: Error :: {0}", ex.ToString());
            }
            return 0;

        }

        public async Task<string[]> GetDBQueryOnlineAlerts(GetBusinessRulesRequest request)
        {
            string[] Result = new string[2];
            try
            {
                string[] columnNames = null;
                if (request.DBType == 1) //sql
                {
                    using (SqlConnection con = new SqlConnection(request.ConnectionString))
                    {
                        con.Open();
                        SqlCommand cmd = new SqlCommand(request.Statement);
                        cmd.Connection = con;
                        SqlDataAdapter da = new SqlDataAdapter(cmd);
                        DataSet ds = new DataSet();
                        da.Fill(ds);

                        columnNames = ds.Tables[0].Columns.Cast<DataColumn>()
                                    .Select(x => x.ColumnName)
                                    .ToArray();

                        if (columnNames.Length == 0)
                        {
                            Result[0] = "0";
                            Result[1] = "Failed";
                            return Result;
                        }
                        else
                        {
                            var tablecolumn = "";
                            for (int i = 0; i < columnNames.Length; i++)
                            {
                                if (tablecolumn == "")
                                {
                                    if (columnNames[i].Contains("[") && columnNames[i].Contains("]"))
                                        tablecolumn = columnNames[i].Replace("[", " ").Replace("]", " ").ToString();
                                    else
                                        tablecolumn = columnNames[i].ToString();
                                }
                                else
                                {
                                    if (columnNames[i].Contains("[") && columnNames[i].Contains("]"))
                                        tablecolumn = tablecolumn + "," + columnNames[i].Replace("[", " ").Replace("]", " ").ToString();
                                    else
                                        tablecolumn = tablecolumn + "," + columnNames[i].ToString();
                                }
                            }
                            Result[0] = "1";
                            Result[1] = tablecolumn;
                            return Result;
                        }
                    }
                }
                else if (request.DBType == 2) //oracle
                {
                    using (OracleConnection orcconn = new OracleConnection(request.ConnectionString))
                    {
                        orcconn.Open();
                        OracleCommand orccmd = new OracleCommand(request.Statement);
                        orccmd.Connection = orcconn;
                        orccmd.CommandText = orccmd.CommandText.Replace(";", "");
                        OracleDataAdapter orcda = new OracleDataAdapter(orccmd);
                        DataSet orcds = new DataSet();
                        orcda.Fill(orcds);
                        columnNames = orcds.Tables[0].Columns.Cast<DataColumn>()
                                    .Select(x => x.ColumnName)
                                    .ToArray();

                        if (columnNames.Length == 0)
                        {
                            Result[0] = "0";
                            Result[1] = "Failed";
                            return Result;
                        }
                        else
                        {
                            var tablecolumn = "";
                            for (int i = 0; i < columnNames.Length; i++)
                            {
                                if (tablecolumn == "")
                                {
                                    if (columnNames[i].Contains("[") && columnNames[i].Contains("]"))
                                        tablecolumn = columnNames[i].Replace("[", " ").Replace("]", " ").ToString();
                                    else
                                        tablecolumn = columnNames[i].ToString();
                                }
                                else
                                {
                                    if (columnNames[i].Contains("[") && columnNames[i].Contains("]"))
                                        tablecolumn = tablecolumn + "," + columnNames[i].Replace("[", " ").Replace("]", " ").ToString();
                                    else
                                        tablecolumn = tablecolumn + "," + columnNames[i].ToString();
                                }
                            }
                            Result[0] = "1";
                            Result[1] = tablecolumn;
                            return Result;
                        }
                    }
                }
            }
            catch (Exception E)
            {
                Result[0] = "1";
                Result[1] = E.ToString();
                return Result;
            }
            return await Task.Run(() => Result);
        }

