        public async Task<int> ChangeOfflineAlertsStatus(ChangeOfflineAlertsStatusRequest request)
        {
            using (var _consumer = new CoreDBConsumer())
            {
                try
                {
                    var res = await _consumer.DbConsumer<ReUsableResponse>("UpdateOnlineAlertsStatus ", SqlEventTypes.Select,
                         new Dictionary<string, object>(){
                    {"@NID",request.NID},
                    {"@NSTATUS",request.NSTATUS},
                    {"@NUPDATEDBY",request.NUPDATEDBY},
                    {"@NUPDATEDUSER",request.NUPDATEDUSER},
                    {"@CurrentStatus",request.CurrentStatus},
                    {"@NRETURN",DBNull.Value},
                    {"@UserIp",request.UserIp}
                    });

                    string strActOrInac = "";

                    if (request.NSTATUS == 1)
                    {
                        //strActOrInac = "Active";

                        strActOrInac = "add";
                    }
                    else
                    {
                        //strActOrInac = "Inactive";

                        strActOrInac = "stop";
                    }

                    if (res.ReturnValue == 1)
                    {
                        try
                        {
                            if (request.NUPDATEDBY == 1)
                            {
                                Logger.InfoFormat("Change-Status: ChangeAlertOnline STARTING from ChangeOfflineAlertsStatus :: Started :: {0}", request.NUPDATEDBY.ToString() + "," + request.NID.ToString() + ", at" + DateTime.Now.ToString());
                                AlertManagerNotificationConsumption servRef = new AlertManagerNotificationConsumption();
                                servRef.PushAlertNotif(request.NUPDATEDBY.ToString(), request.NID.ToString(), strActOrInac);
                                Logger.InfoFormat("Change-Status: ChangeAlertOnline ENDING from ChangeOfflineAlertsStatus :: Ended :: {0}", request.NUPDATEDBY.ToString() + "," + request.NID.ToString() + ", at" + DateTime.Now.ToString());
                            }
                        }
                        catch (Exception ex)
                        {
                            Logger.InfoFormat("ERROR: Change-Status: from ChangeOfflineAlertsStatus :: Ended :: {0}", request.NUPDATEDBY.ToString() + "," + request.NID.ToString() + ", at" + DateTime.Now.ToString() + ", at" + ex.Message.ToString());
                        }
                    }

                    return res.ReturnValue;
                }
                catch (Exception ex)
                {
                    Logger.ErrorFormat("Full Exception Details - UpdateOnlineAlertsStatus ::  {0} & Error :: {1}", ex.StackTrace, ex.ToString());
                }
            }
            return await Task.Run(() => 0);
        }

        public async Task<int> CheckerUpdateOfflineAlerts(ApproveRejectOfflineAlerts request)
        {
            using (var _consumer = new CoreDBConsumer())
            {
                try
                {
                    var res = await _consumer.DbConsumer<ReUsableResponse>("ApproveOrRejectDBAlerts", SqlEventTypes.Select,
                        new Dictionary<string, object>(){
                {"@AlertId",request.AlertId},
                {"@CURRENTSTATUS",request.CURRENTSTATUS},
                {"@UpdatedBy",request.UpdatedBy},
                {"@Rejectreason", (request.Rejectreason ?? "")=="" ? "" : request.Rejectreason.Trim()},
                {"@ReturnValue",DBNull.Value}
                });

                    string opType = "";
                    if (res.ReturnValue == 1)  //call stop notification
                    {
                        opType = "add";

                    }

                    if (res.ReturnValue == 7)   //call stop notification
                    {
                        opType = "stop";

                    }

                    if (res.ReturnValue == 9)
                    {
                        opType = "update";  //call stop notification

                    }



                    //else
                    //{
                    //    opType = "update";
                    //    res.ReturnValue = 1;
                    //}

                    if (request.CURRENTSTATUS == 1)
                    {
                        var alrtResp = "";
                        try
                        {


                            AlertManagerNotificationConsumption servRef = new AlertManagerNotificationConsumption();
                            alrtResp = servRef.PushAlertNotif(request.UpdatedBy.ToString(), request.AlertId.ToString(), opType);
                            Logger.InfoFormat("AddAlertNotification END from InsertOnlineCreation :: ENDED :: {0}", request.UpdatedBy.ToString() + "," + request.AlertId.ToString() + ", at" + DateTime.Now.ToString());

                        }
                        catch (Exception ex)
                        {
                            Logger.InfoFormat("AddAlertNotification ERROR from InsertOnlineCreation :: ERROR :: {0}", request.UpdatedBy.ToString() + "," + request.AlertId.ToString() + ", at" + ex.Message.ToString());
                        }
                    }


                    return res.ReturnValue;
                }
                catch (Exception ex)
                {
                    Logger.ErrorFormat("Full Exception Details - ApproveOrRejectDBAlerts::  {0} & Error :: {1}", ex.StackTrace, ex.ToString());
                }
            }
            return 0;
        }

