        //smsMT-tracking
        public async Task<NewSmsTrackingMain> GetSmstrackingAsync(SmsTrackingRequest request)
        {
            Logger.Info("GetSmstrackingAsync - start : " + DateTime.Now);
            var NewSmsTrackingMain = new NewSmsTrackingMain
            {
                SmsTrackingResponce = new List<SmsTrackingResponce>(),
                SmsTrackingReportView = new List<SmsTrackingReportView>()
            };
            try
            {
                //request.userId=="5" 
                if (request.status == "ALL")
                    request.status = "";

                using (var dbConsumer = new CoreDBConsumer())
                {
                    var Smstracking =
                        await dbConsumer.DbConsumerForMultiItems<DataTable>("GetDlrAlertsReports", SqlEventTypes.Select,
                            new Dictionary<string, object>
                            {
                                {"@StrFromDate", request.FromDate},
                                {"@StrToDate", request.ToDate},
                                //{"@StrFromDate", Convert.ToDateTime(DateTime.ParseExact(request.FromDate, "MM/dd/yyyy",
                                //                    System.Globalization.CultureInfo.InvariantCulture))},
                                //{"@StrToDate", Convert.ToDateTime(DateTime.ParseExact(request.ToDate, "MM/dd/yyyy",
                                //                    System.Globalization.CultureInfo.InvariantCulture))},
                                {"@UserId", request.userId},
                                {
                                    "@Senderid",
                                    (string.IsNullOrWhiteSpace(request.Senderid) && request.Senderid == "0")
                                        ? ""
                                        : request.Senderid
                                },
                                {"@CustomerId", request.CustomerId},
                                {"@Mobileno", request.mobileno ?? ""},
                                {"@Messageid", ""},
                                {"@Country", request.country ?? ""},
                                {"@Operator", request.Operator ?? ""},
                                // {"@Operator","0"},
                                {"@Status", request.status ?? ""},
                                {"@ReturnValue", 0}

                            }, false,
                            DBs.ReportsEngine);

                    if (Smstracking != null && Smstracking.Any())
                    {
                        NewSmsTrackingMain.SmsTrackingResponce = Smstracking[0].ToList<SmsTrackingResponce>();

