                                DBs.ReportsEngine);
                    Logger.Info("GetAdministratorCustomerMTView - Execution ends : " + DateTime.Now);
                    if (responseDTs != null && responseDTs.Any())
                    {
                        smsTrafficMain.AdminReportView = responseDTs[0].ToList<AdminReportView>();
                        Logger.Info("GetAdministratorDailyMTView - Execution start : " + DateTime.Now);
                        var SecoundResult =
                            await
                                dbconsumer.DbConsumerForMultiItems<DataTable>("GetAdministratorDailyMTView",
                                    SqlEventTypes.Select,
                                    new Dictionary<string, object>
                                    {
                                        //{
                                        //    "@strFromDate",
                                        //    Convert.ToDateTime(DateTime.ParseExact(request.FromDate, "MM/dd/yyyy HH:mm:ss",
