                        Logger.Info("GetAdministratorDailyMTView - Execution end : " + DateTime.Now);
                        if (SecoundResult != null && SecoundResult.Any())
                        {
                            smsTrafficMain.SmsTrafficDaysOfMonthResponse = BuildTranficDaysOfMoth(SecoundResult[0]);
                            smsTrafficMain.SmsTrafficDaysOfMonthResponse = SecoundResult[0].ToList<SmsTrafficDaysOfMonthResponse>();
                            Logger.Info("GetAdministratorView - Execution start : " + DateTime.Now);
                            var responseStrip = dbconsumer.DbConsumerForMultiItems<DataTable>("GetAdministratorView",
                                SqlEventTypes.Select,
                                req, false,
                                DBs.ReportsEngine);
                            Logger.Info("GetAdministratorView - Execution end : " + DateTime.Now);
                            if (responseStrip.Result != null)
                            {
                                DataRow row = responseStrip.Result[0].Rows[0];
                                smsTrafficMain.ReportStrip = new ReportStrip
                                {
                                    Delivered =
                                        !string.IsNullOrWhiteSpace(row["Delivered"].ToString())
                                            ? row["Delivered"].ToString()
                                            : string.Empty,
                                    Failed =
                                        !string.IsNullOrWhiteSpace(row["Failed"].ToString())
                                            ? row["Failed"].ToString()
                                            : string.Empty,
                                    Submitted =
                                        !string.IsNullOrWhiteSpace(row["Submitted"].ToString())
