                                Logger.Info("GetCustomerDailyMTView - Execution end : " + DateTime.Now);
                                if (ThirdResult != null && ThirdResult.Any())
                                {
                                    CustomerSmsTrafficMain.CustomerSmsTrafficDaysOfMonthResponse = CustomBuildTranficDaysOfMoth(ThirdResult[0]);
                                    CustomerSmsTrafficMain.CustomerSmsTrafficDaysOfMonthResponse = ThirdResult[0].ToList<CustomerSmsTrafficDaysOfMonthResponse>();

                                    var responsecustrip =
                                        dbconsumer.DbConsumerForMultiItems<DataTable>("GetCustomerView",
                                            SqlEventTypes.Select,
                                            requ, false,
                                            DBs.ReportsEngine);
                                    if (responsecustrip.Result != null)
                                    {
                                        DataRow row = responsecustrip.Result[0].Rows[0];
                                        CustomerSmsTrafficMain.Customeranotherreport = new Customeranotherreport
                                        {
                                            Delivered =
                                                !string.IsNullOrWhiteSpace(row["Delivered"].ToString())
                                                    ? row["Delivered"].ToString()
                                                    : string.Empty,
                                            Failed =
                                                !string.IsNullOrWhiteSpace(row["Failed"].ToString())
                                                    ? row["Failed"].ToString()
                                                    : string.Empty,
                                            Submitted =
                                                !string.IsNullOrWhiteSpace(row["Submitted"].ToString())
                                                    ? row["Submitted"].ToString()
                                                    : string.Empty,
                                            TotalSMS =
