                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            Logger.Info("GetCustomerSmsTrafficOfMonthAsync - end : " + DateTime.Now);
            return CustomerSmsTrafficMain;
        }

        private List<CustomerSmsTrafficDaysOfMonthResponse> CustomBuildTranficDaysOfMoth(DataTable source)
        {
            Logger.Info("CustomBuildTranficDaysOfMoth :: Started");
            var sourceColumns = source.Columns;
            var list = new List<CustomerSmsTrafficDaysOfMonthResponse>();
            try
            {
                foreach (DataColumn column in sourceColumns)
                {
                    var item = new CustomerSmsTrafficDaysOfMonthResponse();
                    foreach (DataRow row in source.Rows)
                    {
                        try
                        {
                            item.Letter = row[0].ToString();
                            item.Freq = Convert.ToInt32(row[1]);
                            list.Add(item);
                        }
                        catch (Exception e)
                        {
                            item.Letter = "";
                            item.Freq = 0;
                            list.Add(item);
                            ErrorSignal.FromCurrentContext().Raise(e);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("CustomBuildTranficDaysOfMoth :: Error :: ", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return list;
        }

