        public async Task<List<SenderConfigurationResponse>> GetSenderConfigurationDetails(GetSenderConfigurationDetailsRequest request)
        {
            Logger.InfoFormat("GetSenderConfigurationDetails :: Started :: {0}", request.SenderConfigId);
            var response = new List<SenderConfigurationResponse>();
            try
            {
                using (var _consumer = new CoreDBConsumer())
                {
                    var dtresponse = await
                        _consumer.DbConsumerForMultiItems<DataTable>("GetSenderMapNI", SqlEventTypes.Select,
                        new Dictionary<string, object>(){
                        {"@CUSTOMERID", request.CustomerId},
                        {"@NUSERID", request.UserId},
                        {"@NSENDERID", request.SenderId},
                        {"@NSTATUS", request.Status},
                        {"@TYPE", ""},
                        {"@RETURNVALUE", DBNull.Value},
                        {"@requestedby",request.RequestPage},
                        {"@UserIp",request.UserIp}
                        //{"@SENDERCONFIGID", request.SenderConfigId}, 
                        //{"@NUSERID", request.CreatedBy}, 
                        //{"@NSTATUS", request.Status},
                        //{"@NRETURN", DBNull.Value}
                    });
                    if (dtresponse != null && dtresponse[0] != null && dtresponse[0].Rows.Count > 0)
                    {
                        response =
                            dtresponse[0].Rows.Cast<DataRow>().Select(s => new SenderConfigurationResponse
                            {
                                ID = Convert.ToInt32(s["ID"].ToString()),
                                CustomerId = Convert.ToInt32(s["CustomerId"].ToString()),
                                Name = s["Name"].ToString(),
                                UserId = Convert.ToInt32(s["UserId"].ToString()),
                                UserName = s["UserName"].ToString(),
                                //BankId = Convert.ToInt32(s["BankId"].ToString()),
                                //BankName = s["BankName"].ToString(),
                                SenderId = Convert.ToInt32(s["SenderId"].ToString()),
                                SMSChannel = Convert.ToBoolean(s["SMSChannel"]),
                                EmailChannel = Convert.ToBoolean(s["EmailChannel"]),
                                CardBin = !string.IsNullOrWhiteSpace(s["CardBin"].ToString()) ? Convert.ToInt32(s["CardBin"].ToString()) : 0,
                                CardBinNo = s["CardBinNo"].ToString(),
                                Module = !string.IsNullOrWhiteSpace(s["Module"].ToString()) ? Convert.ToInt32(s["Module"].ToString()) : 0,
                                Code = s["Code"].ToString(),
                                Status = Convert.ToInt32(s["Status"].ToString()),
                                CurrentStatus = Convert.ToInt32(s["CurrentStatus"].ToString()),
                                RejectNote = s["RejectNote"].ToString(),
                                CreatedBy = Convert.ToInt32(s["CreatedBy"].ToString()),
                                //CardBinNo = s["CardBinNo"].ToString()
                            }).ToList();
                        //if (response.Any())
                        //{
                        //    response =
                        //        response.GroupBy(g => new { g.CustomerId, g.UserId, g.SenderId, g.BankId, g.CardBin })
                        //            .Select(s => s.First())
                        //            .ToList();
                        //}

                        if (response.Any())
                        {
                            response =
                                response.GroupBy(g => new { g.CustomerId, g.UserId, g.SenderId, g.CardBin })
                                    .Select(s => s.First())
                                    .ToList();
                        }
                    }
                    Logger.InfoFormat("GetSenderConfigurationDetails :: End :: GetSenderConfigurationDetails :: {0} ", response.Count);
                    return response;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("GetSenderConfigurationDetails :: Error :: {0}", ex.ToString());
            }
            return new List<SenderConfigurationResponse>();
        }

