        public async Task<RegisteremailSaveResponse> SaveOrUpdateRegisteredFromMail(RegisterEmailRequest request)
        {
            Logger.InfoFormat("SaveRegisteredFromMail :: Start :: Frommail - {0} & CreatedBy - {1}", request.FromEmail, request.CreatedBy);
            try
            {
                using (var dbConsumer = new CoreDBConsumer())
                {
                    var respone = await dbConsumer.DbConsumer<ReUsableResponse>("SaveFromEmail", SqlEventTypes.Select,
                        new Dictionary<string, object>
                        {
                            {"@Id", request.Id},
                            {"@FromEmail", request.FromEmail},
                            {"@Status", request.Status},
                            {"@CreatedBy", request.CreatedBy},
                            {"@CurrentStatus", request.CurrentStatus},
                            {"@RejectReason", request.RejectReason},
                            {"@UserIp", request.UserIp}
                        });
                    switch (respone.NRETVAL)
                    {
                        case -0:
                            return new RegisteremailSaveResponse { IsValid = false, Message = "From mail already existed in db." };
                        case -1:
                            return new RegisteremailSaveResponse { IsValid = false, Message = "While executing sp fattal error occured." };
                        case 1:
                            return new RegisteremailSaveResponse
                            {
                                IsValid = true,
                                Message = ((request.Id == 0) ? "Email Registered Successfully" : "Email Updated Successfully")
                            };
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("SaveRegisteredFromMail - Fatal error :: {0} ", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return new RegisteremailSaveResponse { IsValid = false, Message = "error occured." };
        }

        public async Task<RegisteremailSaveResponse> ValidateFromMail(RegisterEmailRequest request)
        {
            Logger.InfoFormat("ValidateFromMail :: Start :: Frommail - {0}", request.FromEmail);
            try
            {
                using (var dbConsumer = new CoreDBConsumer())
                {
                    var respone = await dbConsumer.DbConsumer<ReUsableResponse>("ValidateFromEmail", SqlEventTypes.Select,
                        new Dictionary<string, object>
                        {
                            {"@FromEmail", request.FromEmail}
                        });
                    switch (respone.NRETVAL)
                    {
                        case -0:
                            return new RegisteremailSaveResponse { IsValid = false, Message = "Email id is already registered" };
                        case -1:
                            return new RegisteremailSaveResponse { IsValid = false, Message = "While executing sp fattal error occured." };
                        case 1:
                            return new RegisteremailSaveResponse
                            {
                                IsValid = true,
                                Message = "Success"
                            };

                    }
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("ValidateFromMail - Fatal error :: {0} ", ex.ToString());
