        public async Task<RegisteremailSaveResponse> SaveOrUpdateEmailCampaign(EmailCampaignPDb request)
        {
            Logger.InfoFormat("SaveOrUpdateEmailCampaign :: Start :: CampaingName - {0} & Id - {1}", request.CampaignName, request.Id);
            try
            {
                using (var dbConsumer = new CoreDBConsumer())
                {
                    var respone =
                        await dbConsumer.DbConsumer<ReUsableResponse>("SetOrUpdateEPNCampaign", SqlEventTypes.Select,
                            new Dictionary<string, object>
                            {
                                {"@CustomerID", request.CustomerId},
                                {"@CampID", request.Id},
                                {"@Name", request.CampaignName},
                                {"@SenderId", request.FromMail},
                                {"@CampaignTypeID", 1}, // 1 - bulk, 2 - custom
                                {"@Message", request.MessageBody},
                                {"@CharCount", request.MessageBody.Length},
                                {"@ScheduledType", request.ScheduleType},
                                {"@PlaceHolders", ""}, // need to add
                                {"@AllowDuplicates", 1}, //need to add
                                {"@MessageType", request.MessageType},
                                {"@Status", request.Status},
                                {"@CreatedBy", request.CreatedBy},
                                {"@ChannelType", request.ChannelType.ToString()}, // --
                                {"@CurrentStatus", request.CurrentStatus},
                                {"@ImportFileName", request.FileName},
                                {"@ActualFileName", request.ActualFileName},
                                {"@SheetName", ""}, //need to add
                                {"@ValidCount", request.ValidCount},
                                {"@InvalidCount", request.InvalidCount},
                                {"@DuplicateCount", request.DuplicateCount},
                                {"@RecipientsType", GetReciepentType(Path.GetExtension(request.FileName))},
                                // 1 - xls, 2 - xlsx, 3 -csv, 4 - txt
                                {"@RecipientField", ""}, // need to add
                                {"@GroupIds", ""}, // need to add
                                {"@IsDone", 0}, // need to add
                                {"@TotalCount", request.TotalCount},
                                {"@ProcessedCount", request.ValidCount}, // need to add
                                {
                                    "@Schedule",
                                    !string.IsNullOrWhiteSpace(request.StartDate)
                                        ? Convert.ToDateTime(request.StartDate)
                                            .AddHours(Convert.ToInt32(request.StartTime))
                                            .AddMinutes(Convert.ToInt32(request.StartMinutes))
                                        : DateTime.Now
                                },
                                {"@TotalCreditsReq", 0}, // need to add
                                {"@UserIp", request.UserIp},
                                {"@EmailSubject", request.EmailSubject ?? ""},
                                {"@nReturn", DBNull.Value},
                                {"@CAMPAIGNID", DBNull.Value}
                            });
                    switch (respone.nReturn)
                    {
                        case 1:
                            return new RegisteremailSaveResponse
                            {
                                IsValid = false,
                                CampId = respone.CampId,
                                Message = "Customer/User is in inactive state."
                            };
                        case 5:
                            return new RegisteremailSaveResponse
                            {
                                IsValid = true,
                                CampId = respone.CampId,
                                Message = "Campaign updated successfully."
                            };
                        case 7:
                            return new RegisteremailSaveResponse
                            {
                                IsValid = true,
                                CampId = respone.CampId,
                                Message = "Campaign created successfully."
                            };
                        case 8:
                            return new RegisteremailSaveResponse
                            {
                                IsValid = false,
                                CampId = respone.CampId,
                                Message = "campaign Name existed with given name, please choose another name."
                            };
                        case 9:
                            return new RegisteremailSaveResponse
                            {
                                IsValid = false,
                                CampId = respone.CampId,
                                Message = "Schedule date is less than current time stamp."
                            };
                        case 11:
                            return new RegisteremailSaveResponse
                            {
                                IsValid = false,
                                CampId = respone.CampId,
                                Message = "Campaign preprocess started, not allowed for edit."
                            };
                        case -1:
                            return new RegisteremailSaveResponse
                            {
                                IsValid = false,
                                CampId = respone.CampId,
                                Message = "While executing sp fattal error occured."
                            };
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("SaveOrUpdateEmailCampaign - Fatal error :: {0} ", ex.ToString());
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return new RegisteremailSaveResponse
            {
                IsValid = false,
                CampId = 0,
                Message = "Fatal error occured"
            };
        }

        public async Task<int> SetPNCampActivities(EmailCampaignPDb request)
        {
            Logger.InfoFormat("SetPNCampActivities :: start :: {0}", request.Id);
            try
            {
                using (var _consumer = new CoreDBConsumer())
                {
                    var response = await _consumer.DbConsumer<ReUsableResponse>("SetEPNCampaignStatus", SqlEventTypes.Select,
                        new Dictionary<string, object> {
                    {"@CampID",request.Id},
                    {"@Status",request.Status},
                    {"@ChannelType",request.ChannelType},
                    {"@CreatedBy",request.CreatedBy},
                    {"@UserIp",request.UserIp},
                    {"@Name", request.CampaignName ?? ""},
                    {"@nReturn",DBNull.Value}
                    });
                    if (response.nReturn == 4)
                    {
                        var QMsg = "action=stop&camp_id=" + request.Id + "&camp_type=2&dir_name=" + response.dirname + "&count=" + response.tcount + "&channel=" + request.ChannelType;
                        var qresult = new CampaignQLog().PushMessageToQ(QMsg, System.Configuration.ConfigurationManager.AppSettings["EmailPushNotificationQ"]);
                    }
                    return response.nReturn;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("Fatal Error thouging from SetPNCampActivities :: {0} ", ex.StackTrace);
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return 0;
        }

