        private int GetReciepentType(string extension)
        {
            switch (extension.ToLower())
            {
                case ".xls":
                    return 1;
                case ".xlsx":
                    return 2;
                case ".csv":
                    return 3;
                case ".txt":
                    return 4;
                default:
                    return 0;

            }
        }

