                using (var dbConsumer = new CoreDBConsumer())
                {
                    var response =
                        await
                            dbConsumer.DbConsumer<ReUsableResponse>("SaveOrUpdateRegisterPushNotification",
                                SqlEventTypes.Select,
                                new Dictionary<string, object>
                                {
                                    {"@Id", request.Id},
