        #region Vitis Refresh

        public async Task<string> BuildConfigurationData(string type, string smscid = null, string groupname = null, string esmeid = null)
        {
            try
            {
                _SynapseCoreData();
                Logger.InfoFormat("BuildConfigurationData connection factory - BROKER :: {0} & CLIENT_ID :: {1}", BROKER, CLIENT_ID);
                switch (type.ToUpper())
                {
                    case GsmData.Server:
                        await GenerateSmppServerData();
                        Logger.Info("serverconfig xml trigger generated.");
                        return GsmData.Success;
                    case GsmData.Client:
                        await GenerateSmppClientData();
                        Logger.Info("clientconfig xml trigger generated.");
                        return GsmData.Success;
                    case GsmData.Hlr:
                        await GenerateHlrData();
                        Logger.Info("HLR data xml trigger generated.");
                        return GsmData.Success;
                    case GsmData.Route:
                        await GenerateRouteData();
                        Logger.Info("routeconfig xml trigger generated.");
                        return GsmData.Success;
                    case GsmData.Filter:
                        await GenerateFilterWordsData();
                        Logger.Info("Filterwords xml trigger generated.");
                        return GsmData.Success;
                    case GsmData.Smppsenders:
                        await GenerateSmppSendersData();
                        Logger.Info("SmppSenders xml trigger generated.");
                        return GsmData.Success;
                    case GsmData.Users:
                        await GenerateUsersData();
                        Logger.Info("Users xml trigger generated.");
                        return GsmData.Success;
                    case GsmData.Dnd:
                        await GenerateDndData();
                        Logger.Info("DND data xml trigger generated.");
                        return GsmData.Success;
                    case GsmData.Bind:
                    case GsmData.Unbind:
                    case GsmData.Restart:
                        using (var publisher = new TopicPublisher(session, TOPIC_NAME))
                        {
                            //+ "\"" + type.ToLower() + "\"" +
                            //+ "\"update\"" +

                            //publisher.SendMessage("Refresh app updated.");
                            publisher.SendMessage("<root id=" + "\"" + groupname + "\"" + "><esme id=" + "\"" + smscid + "\"" +
                                                          "><action type=" + "\"" + type.ToLower() + "\"" + "><fields>" +
                                                          DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss.fff tt") +
                                                          "</fields></action></esme></root>");
                        }
                        //connection.Close();
                        Logger.Info("SMSC trigger generate for: " + GsmData.Bind);
                        return GsmData.Success;
                    case GsmData.Gsmdata:
                        await GenerateGSMCharsetData();
                        Logger.Info("GSMCharset data trigger generated");
                        return GsmData.Success;
                }
            }
            catch (Exception ex)
            {
                var error = ex.ToString();
                Logger.Info(error);
            }
            return string.Empty;
        }

        #region Parameter Based functions

        #region Server

        private async Task GenerateSmppServerData()
        {
            if (!Directory.Exists(_filePath))
                Directory.CreateDirectory(_filePath);
            try
            {
                using (var dbConsumer = new CoreDBConsumer())
                {
                    var response =
                        await
                            dbConsumer.DbConsumerForMultiItems<DataTable>(
                                (System.Configuration.ConfigurationManager.AppSettings["ADOProvider"].Equals(GsmData.Npgsql,
                                    StringComparison.OrdinalIgnoreCase)
                                    ? "udpgetconfigurationdata_server"
                                    : "udpGetConfigurationData"),
                                SqlEventTypes.Select,
                                new Dictionary<string, object>
                                {
                                    {"@type", GsmData.Server},
                                    {"@ReturnValue", DBNull.Value}
                                });

                    if (response != null && response.Any() && response[0].Rows.Count > 0)
                    {
                        var distinctRows = (from DataRow dRow in response[0].Rows
                                            select new { portcol1 = dRow["port"].ToString().ToLower(), Instance1 = dRow["Instance"].ToString() }).GroupBy(g => g.portcol1.ToString().ToLower())
                            .Select(s => s.First())
                            .Distinct();

                        //var distinctRows = (from DataRow dRow in response[0].Rows
                        //                    select new { portcol1 = dRow["port"] }).Distinct();

                        var ServerConfigfiles = GetFilesCollection("serverconfig_");
                        var removedFiles = RemovedServerFiles(ServerConfigfiles, distinctRows);
                        foreach (var item in distinctRows)
                        {

                            try
                            {

                                var xDoc = new XDocument(new XElement("root",
                                    new XAttribute("id", item.Instance1),
                                    new XElement("port", System.Configuration.ConfigurationManager.AppSettings["SMPP_PORT"] ?? "8090"),
                                    new XElement("maxConnectionsSize",
                                        System.Configuration.ConfigurationManager.AppSettings["SMPP_MAX_CONN"] ?? "20"),
                                    from p in response[0].Select("Port=" + item.portcol1.ToString()).AsEnumerable()

                                    select new XElement("esme",
                                        new XAttribute("id", p["UserID"] != null ? p["UserID"].ToString() : string.Empty),
                                        new XElement("whitelistedips",
                                            p["whiteListedIPs"] != null ? p["whiteListedIPs"].ToString() : string.Empty),
                                        new XElement("systemid",
                                            p["UserName"] != null ? p["UserName"].ToString() : string.Empty),
                                        new XElement("password",
                                            p["Password"] != null ? p["Password"].ToString() : string.Empty),
                                        //new XElement("password", p["Password"] != null ? AppInternalEncKey.Decrypt(p["Password"].ToString(), false) : string.Empty),
                                        new XElement("systemtype",
                                            p["SystemType"] != null ? p["SystemType"].ToString() : string.Empty),
                                        new XElement(new XElement("bindmodes",
                                            new XElement("bind",
                                                new XElement("mode", "TRX"),
                                                new XElement("sessions",
                                                    p["Transiver"] != null ? p["Transiver"].ToString() : string.Empty)),
                                            new XElement("bind",
                                                new XElement("mode", "TX"),
                                                new XElement("sessions",
                                                    p["Transmeter"] != null ? p["Transmeter"].ToString() : string.Empty)),
                                            new XElement("bind",
                                                new XElement("mode", "RX"),
                                                new XElement("sessions",
                                                    p["Receiver"] != null ? p["Receiver"].ToString() : string.Empty)))),
                                        new XElement("version",
                                            p["Version"] != null ? p["Version"].ToString() : string.Empty),
                                        new XElement("throughput",
                                            p["Throughput"] != null ? p["Throughput"].ToString() : string.Empty),
                                        new XElement("addressrange",
                                            p["AddRange"] != null ? p["AddRange"].ToString() : string.Empty),
                                        new XElement("addressrangenpi",
                                            p["AddRangeNPI"] != null ? p["AddRangeNPI"].ToString() : string.Empty),
                                        new XElement("addressrangeton",
                                            p["AddRangeTON"] != null ? p["AddRangeTON"].ToString() : string.Empty),
                                        new XElement("enquiryinterval",
                                            p["EnquiryInterval"] != null
                                                ? p["EnquiryInterval"].ToString()
                                                : string.Empty),
                                        new XElement("port", p["Port"] != null ? p["Port"].ToString() : string.Empty),
                                        new XElement("ipaddress",
                                            p["IPaddress"] != null ? p["IPaddress"].ToString() : string.Empty),
                                        new XElement("charset", p["CharSet"] != null ? p["CharSet"].ToString() : string.Empty),
                                        new XElement("dcs", p["DCS"] != null ? p["DCS"].ToString() : string.Empty),
                                        new XElement("assamblelongmessages", p["AssembleLongMessages"] != null ? p["AssembleLongMessages"].ToString() : string.Empty),
                                        new XElement("ton", p["TON"] != null ? p["TON"].ToString() : string.Empty),
                                        new XElement("npi", p["NPI"] != null ? p["NPI"].ToString() : string.Empty))
                                    ));

                                BuildChangeSetsServerConfig(GetFilesCollection("serverconfig_"), xDoc, item.portcol1.ToString(),
                                    "serverconfig_", item.Instance1);

                                if (IsValidXml(xDoc.ToString()))
                                    xDoc.Save(Path.Combine(_filePath, "serverconfig_" + item.portcol1.ToString() + ".xml"));
                            }
                            catch (Exception ex)
                            {
                                var err = ex.ToString();
                                Logger.Info(err);
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                var error = ex.ToString();
                Logger.Info(error);
            }
        }

