        #region Route

        private async Task GenerateRouteData()
        {
            if (!Directory.Exists(_filePath))
                Directory.CreateDirectory(_filePath);
            try
            {
                using (var dbConsumer = new CoreDBConsumer())
                {
                    var response =
                        await
                            dbConsumer.DbConsumerForMultiItems<DataTable>(
                                (System.Configuration.ConfigurationManager.AppSettings["ADOProvider"].Equals(GsmData.Npgsql,
                                    StringComparison.OrdinalIgnoreCase)
                                    ? "udpgetconfigurationdata_route"
                                    : "udpGetConfigurationData"),
                                SqlEventTypes.Select,
                                new Dictionary<string, object>
                                {
                                    {"@type", GsmData.Route},
                                    {"@ReturnValue", DBNull.Value}
                                });
                    if (response != null && response.Any() && response[0].Rows.Count > 0)
                    {
                        var routeResponse = response[0].ToList<RouteResponse>();

                        if (routeResponse.Any())
                        {
                            var beforeFileter = routeResponse;
                            var filterResponse =
                                beforeFileter.GroupBy(g => new
                                {
                                    g.CUSTOMERID,
                                    g.USERID,
                                    g.SMSCID,
                                    g.SENDERID,
                                    g.TOTMOBILELEN,
                                    g.COUNTRY,
                                    g.OPERATORID,
                                    g.DEFROUTE
                                })
                                    .Select(s => s.First());
                            if (filterResponse.Any())
                            {
                                var ROUTEConfigfile = GetFilesCollection("routeconfig");

                                var xDoc = new XDocument(new XElement("root",
                              (from item in filterResponse
                               let serries =
                                   routeResponse.Where(
                                       w =>
                                           w.CUSTOMERID == item.CUSTOMERID && w.USERID == item.USERID &&
                                           w.SMSCID == item.SMSCID && w.SENDERID == item.SENDERID
                                           && w.TOTMOBILELEN == item.TOTMOBILELEN && w.COUNTRY == item.COUNTRY
                                           && w.OPERATORID == item.OPERATORID && w.DEFROUTE == item.DEFROUTE)
                                       .Select(s => s.SERIES)
                               select new XElement("route",
                                   new XAttribute("smscid", item.SMSCID ?? string.Empty),
                                   new XElement("routeid", !string.IsNullOrWhiteSpace(item.ROUTEID) ? item.ROUTEID : string.Empty),
                                   new XElement("customerid", !string.IsNullOrWhiteSpace(item.CUSTOMERID) ? item.CUSTOMERID : string.Empty),
                                   new XElement("userid", !string.IsNullOrWhiteSpace(item.USERID) ? item.USERID : string.Empty),
                                   new XElement("country", !string.IsNullOrWhiteSpace(item.COUNTRY) ? item.COUNTRY : string.Empty),
                                   new XElement("countryname", !string.IsNullOrWhiteSpace(item.COUNTRYNAME) ? item.COUNTRYNAME : string.Empty),
                                   new XElement("len_country", !string.IsNullOrWhiteSpace(item.LEN_COUNTRY) ? item.LEN_COUNTRY : string.Empty),
                                   new XElement("mobilelen", !string.IsNullOrWhiteSpace(item.MOBILELEN) ? item.MOBILELEN : string.Empty),
                                   new XElement("totmobilelen", !string.IsNullOrWhiteSpace(item.TOTMOBILELEN) ? item.TOTMOBILELEN : string.Empty),
                                   new XElement("operatorid", !string.IsNullOrWhiteSpace(item.OPERATORID) ? item.OPERATORID : string.Empty),
                                   new XElement("series", string.Join(",", serries)),
                                   new XElement("smsc", !string.IsNullOrWhiteSpace(item.SMSC) ? item.SMSC : string.Empty),
                                   new XElement("defroute", (!string.IsNullOrWhiteSpace(item.DEFROUTE) && item.DEFROUTE.ToLower().Equals("true")) ? "true" : "false"),
                                   new XElement("prefroute", (!string.IsNullOrWhiteSpace(item.DEFROUTE) && item.DEFROUTE.ToLower().Equals("false")) ? "true" : "false"),
                                   new XElement("sender", !string.IsNullOrWhiteSpace(item.SENDER) ? item.SENDER : string.Empty),
                                   new XElement("senderid", !string.IsNullOrWhiteSpace(item.SENDERID) ? item.SENDERID : string.Empty),
                                   new XElement("vendorid", !string.IsNullOrWhiteSpace(item.VENDORID) ? item.VENDORID : string.Empty))
                                  )));

                                if (IsValidXml(xDoc.ToString()))
                                {
                                    BuildChangeSetsRoute(ROUTEConfigfile, xDoc, "routeconfig.xml");
                                    xDoc.Save(Path.Combine(_filePath, "routeconfig.xml"));
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                var error = ex.ToString();
                Logger.Info(error);
            }
        }

