                                new XElement("http", p["http"] != null ? p["http"].ToString().ToLower() : string.Empty),
                                new XElement("smpp", p["SMPP"] != null ? p["SMPP"].ToString().ToLower() : string.Empty),
                                new XElement("customerid", p["CustomerId"] != null ? p["CustomerId"].ToString() : string.Empty))
                          ));

                        if (IsValidXml(xDoc.ToString()))
                        {
                            BuildChangeSetsUser(UserConfigfile, xDoc, "users.xml");
                            xDoc.Save(Path.Combine(_filePath, "users.xml"));
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                var error = ex.ToString();
                Logger.Info(error);
            }
        }

