        private List<FileInfo> GetFilesCollection(string aliasName)
        {
            var hdDirectoryInWhichToSearch = new DirectoryInfo(_filePath);
            var filesInDir = hdDirectoryInWhichToSearch.GetFiles("*" + aliasName + "*.*");
            return filesInDir.Select(foundFile => foundFile).ToList();
        }

        private string RemovedClientFiles(List<FileInfo> files, dynamic distInstences)
        {

            foreach (var item in distInstences)
            {
                var fi = files.FirstOrDefault(f => f.Name.Equals("clientconfig_" + item.Instance1 + ".xml"));
                if (fi != null)
                {
                    files.Remove(fi);
                }
            }

            if (files.Any())
            {
                var removedports = string.Empty;
                foreach (var it in files)
                {
                    var oldXmlDoc = new XmlDocument();
                    oldXmlDoc.Load(Path.Combine(_filePath, it.Name));
                    var oldXDoc = XDocument.Parse(oldXmlDoc.InnerXml);

                    // + "\"" + it.Name.Split('_')[1] + "\"" +
                    // "+ "\"remove\"" +"

                    foreach (var ne in oldXDoc.Root.Elements(XName.Get("esme")))
                    {
                        removedports += "<esme id=" + "\"" + ne.Attribute(XName.Get("id")).Value.Trim() + "\"" +
                                              "><action type=" + "\"remove\"" + "/></esme>";
                    }

                    if (!string.IsNullOrWhiteSpace(removedports))
                    {
                        using (var publisher = new TopicPublisher(session, TOPIC_NAME))
                        {
                            //publisher.SendMessage(removedports);
                            char[] arr = new char[] { '.', 'x', 'm', 'l' };
                            string rootid = it.Name.Split('_')[1].TrimEnd(arr);
                            publisher.SendMessage("<root id=" + "\"" + rootid + "\"" + ">" + removedports + "</root>");
                        }
                    }

                    File.Delete(Path.Combine(_filePath, it.Name));
                }
            }


            //if(files.Any())
            //{
            //    var removedports = string.Empty;
            //    foreach(var it in files)
