        private void BuildChangeSetsServerConfig(List<FileInfo> files, XDocument xDoc, string keyName, string aliasName, string Instance)
        {
            var selectedfile = files.FirstOrDefault(f => f.Name.Equals(aliasName + keyName + ".xml"));
            if (selectedfile != null)
            {
                var oldXmlDoc = new XmlDocument();
                oldXmlDoc.Load(selectedfile.FullName);
                var oldXDoc = XDocument.Parse(oldXmlDoc.InnerXml);

                var oldChangeSetResult = from o in oldXDoc.Root.Elements(XName.Get("esme"))
                                         join n in xDoc.Root.Elements(XName.Get("esme")) on o.Attribute(XName.Get("id")).Value equals
                                             n.Attribute(XName.Get("id")).Value
                                         select new { o, n };

                #region Commented working
                var nelements = new List<XElement>();
                foreach (var ne in xDoc.Root.Elements(XName.Get("esme")))
                {
                    var fe =
                        oldXDoc.Root.Elements(XName.Get("esme"))
                            .FirstOrDefault(
                                f =>
                                    f.Attribute(XName.Get("id"))
                                        .Value.Trim()
                                        .Equals(ne.Attribute(XName.Get("id")).Value.Trim()));
                    if (fe == null)
                    {
                        nelements.Add(ne);
                    }
                }

                #endregion

                var r1 = ValidateOldElements(oldChangeSetResult.Distinct());

                var removedElements = (from item in oldXDoc.Root.Elements(XName.Get("esme"))
                                       let sElements =
                                           xDoc.Root.Elements(XName.Get("esme"))
                                               .FirstOrDefault(
                                                   f =>
                                                       f.Attribute(XName.Get("id"))
                                                           .Value.Equals(item.Attribute(XName.Get("id")).Value,
                                                               StringComparison.OrdinalIgnoreCase))
                                       where sElements == null
                                       select item).Aggregate(string.Empty,
                        (current, item) =>
                            current +
                            ("<esme id=" + "\"" + item.Attribute(XName.Get("id")).Value + "\"" +
                             "><action type=" + "\"remove\"" + "></action></esme>"));

                // + "\"" + item.Attribute(XName.Get("id")).Value + "\"" +
                // "+ "\"remove\"" +"

                var finalxml = string.Empty;
                //if (!string.IsNullOrWhiteSpace(nelements.ToString()))
                if (nelements.Count > 0)
                {
                    //finalxml += string.Join("", nelements);
                    foreach (var ne1 in nelements)
                        finalxml += "<esme id=" + "\"" + ne1.Attribute(XName.Get("id")).Value + "\"" +
                             "><action type=" + "\"update\"" + "><fields>update</fields></action></esme>";
                }
                if (!string.IsNullOrWhiteSpace(r1))
                {
                    finalxml += r1;
                }
                if (!string.IsNullOrWhiteSpace(removedElements.ToString()))
                {
                    finalxml += removedElements.ToString();
                }

                if (!string.IsNullOrWhiteSpace(finalxml.Trim()) && finalxml.Trim() != "")
                {
                    // + "\"" + keyName + "\"" +
                    // "+ "\"remove\"" +"

                    //xDoc.Save(Path.Combine(_filePath, keyName + "_changes.xml"));
                    using (var publisher = new TopicPublisher(session, TOPIC_NAME))
                    {
                        //publisher.SendMessage("Refresh app updated.");
                        publisher.SendMessage("<root id=" + "\"" + Instance + "\"" + ">" + finalxml + "</root>");
                    }
                    //connection.Close();
                }
            }

            else //New group or new port xml file
            {
                var nelements = new List<XElement>();
                foreach (var ne in xDoc.Root.Elements(XName.Get("esme")))
                    nelements.Add(ne);

                var finalxml = string.Empty;
                if (nelements.Count > 0)
                {
                    //finalxml += string.Join("", nelements);
                    foreach (var ne1 in nelements)
                        finalxml += "<esme id=" + "\"" + ne1.Attribute(XName.Get("id")).Value + "\"" +
                             "><action type=" + "\"update\"" + "><fields>update</fields></action></esme>";
                }

                if (!string.IsNullOrWhiteSpace(finalxml.Trim()) && finalxml.Trim() != "")
                {
                    //xDoc.Save(Path.Combine(_filePath, keyName + "_changes.xml"));

                    // + "\"" + keyName + "\"" +
                    // "+ "\"remove\"" +"

                    using (var publisher = new TopicPublisher(session, TOPIC_NAME))
                    {
                        //publisher.SendMessage("Refresh app updated.");
                        publisher.SendMessage("<root id=" + "\"" + Instance + "\"" + ">" + finalxml + "</root>");
                    }
                    //connection.Close();
                }
            }
        }

