        private void BuildChangeSetsRoute(List<FileInfo> files, XDocument xDoc, string aliasName)
        {
            //<root id="cache">
            //<user id="2" type="route">
            //    <action type="update" />
            //</user>
            //<user id="11" type="dns">
            //    <action type="update" />
            //</user>
            //</root>
            try
            {
                var selectedfile = files.FirstOrDefault(f => f.Name.Equals(aliasName));
                if (selectedfile != null)
                {
                    var oldXmlDoc = new XmlDocument();
                    oldXmlDoc.Load(selectedfile.FullName);
                    var oldXDoc = XDocument.Parse(oldXmlDoc.InnerXml);

                    var tempOldElements = CovertXmlToRoutesTempModel(oldXDoc);

                    var tempNewElements = CovertXmlToRoutesTempModel(xDoc);

                    var removedlist =
                        tempOldElements.Where(
                            w =>
                                !tempNewElements.Any(
                                    a => w.smscid == a.smscid && a.UserId == w.UserId && a.RouteId == w.RouteId))
                            .ToList();

                    var newlist =
                        tempNewElements.Where(
                            w =>
                                !tempOldElements.Any(
                                    a => w.smscid == a.smscid && a.UserId == w.UserId && a.RouteId == w.RouteId))
                            .ToList();
                    var commonlist =
                        tempOldElements.Where(
                            w =>
                                tempNewElements.Any(
                                    a => w.smscid == a.smscid && a.UserId == w.UserId && a.RouteId == w.RouteId))
                            .ToList();

                    /* Changeset start */
                    #region for changesets
                    var updateditems = (from item in commonlist
                                        let oitem =
                                            tempOldElements.FirstOrDefault(
                                                f =>
                                                    f.smscid.Equals(item.smscid, StringComparison.OrdinalIgnoreCase) &&
                                                    f.RouteId.Equals(item.RouteId, StringComparison.OrdinalIgnoreCase) &&
                                                    f.UserId.Equals(item.UserId, StringComparison.OrdinalIgnoreCase))
                                        let nitem =
                                            tempNewElements.FirstOrDefault(
                                                f =>
                                                    f.smscid.Equals(item.smscid, StringComparison.OrdinalIgnoreCase) &&
                                                    f.RouteId.Equals(item.RouteId, StringComparison.OrdinalIgnoreCase) &&
                                                    f.UserId.Equals(item.UserId, StringComparison.OrdinalIgnoreCase))
                                        where oitem != null && nitem != null
                                        where !Compare<RoutesTempModel>(oitem, nitem)
                                        select nitem).ToList();

                    updateditems.AddRange(removedlist);
                    updateditems.AddRange(newlist);

                    updateditems = updateditems.GroupBy(g => g.UserId).Select(s => s.First()).ToList();

                    var finalxml = updateditems.Aggregate(string.Empty,
                         (current, re) =>
                             current +
                             (@"<user id=" + "\"" + re.UserId + "\"" + " type=" + "\"route\"" + "><action type=" + "\"update\"" + "></action></user>"));

                    // + "\"" + re.UserId + "\"" +
                    // "+ "\"cache\"" +"

                    #endregion

                    if (!string.IsNullOrWhiteSpace(finalxml.Trim()) && finalxml.Trim() != "")
                    {
                        using (var publisher = new TopicPublisher(session, TOPIC_NAME))
                        {
                            //publisher.SendMessage("Refresh app updated.");
                            publisher.SendMessage("<root id=" + "\"cache\"" + ">" + finalxml + "</root>");
                        }
                        //connection.Close();
                    }
                }

                else //New route file
                {
                    var tempNewElements = CovertXmlToRoutesTempModel(xDoc);

                    tempNewElements = tempNewElements.GroupBy(g => g.UserId).Select(s => s.First()).ToList();

                    // + "\"" + re.UserId + "\"" +
                    // "+ "\"cache\"" +"

                    var finalxml = tempNewElements.Aggregate(string.Empty,
                         (current, re) =>
                             current +
                             (@"<user id='" + re.UserId + "' type=" + "\"route\"" + "><action type=" + "\"update\"" + "></action></user>"));

                    if (!string.IsNullOrWhiteSpace(finalxml.Trim()) && finalxml.Trim() != "")
                    {
                        using (var publisher = new TopicPublisher(session, TOPIC_NAME))
                        {
                            //publisher.SendMessage("Refresh app updated.");
                            publisher.SendMessage("<root id=" + "\"cache\"" + ">" + finalxml + "</root>");
                        }
                        //connection.Close();
                    }
                }


            }
            catch (Exception ex)
            {
                var exp = ex.Message;
                Logger.Info(exp);
            }
        }

