            //    <action type="update" />
            //</user>
            //<user id="11" type="dns">
            //    <action type="update" />
            //</user>
            //</root>

            try
            {
                var selectedfile = files.FirstOrDefault(f => f.Name.Equals(aliasName));
                if (selectedfile != null)
                {
                    var oldXmlDoc = new XmlDocument();
                    oldXmlDoc.Load(selectedfile.FullName);
                    var oldXDoc = XDocument.Parse(oldXmlDoc.InnerXml);


                    // start code to be verify
                    var tempOldElements = CovertXmlToSmppSenderTempModel(oldXDoc);

                    var tempNewElements = CovertXmlToSmppSenderTempModel(xDoc);

                    var removedlist =
                        tempOldElements.Where(
                            w =>
                                !tempNewElements.Any(
                                    a => w.senderid == a.senderid && a.userid == w.userid))
                            .ToList();

                    var newlist =
                        tempNewElements.Where(
                            w =>
                                !tempOldElements.Any(
                                    a => w.senderid == a.senderid && a.userid == w.userid))
                            .ToList();
                    var commonlist =
                        tempOldElements.Where(
                            w =>
                                tempNewElements.Any(
                                    a => w.senderid == a.senderid && a.userid == w.userid))
                            .ToList();

                    var updateditems = (from item in commonlist
                                        let oitem =
                                            tempOldElements.FirstOrDefault(
                                                f =>
                                                    f.senderid.Equals(item.senderid, StringComparison.OrdinalIgnoreCase) &&
                                                    f.userid.Equals(item.userid, StringComparison.OrdinalIgnoreCase))

                                        let nitem =
                                            tempNewElements.FirstOrDefault(
                                                f =>
                                                    f.senderid.Equals(item.senderid, StringComparison.OrdinalIgnoreCase) &&
                                                    f.userid.Equals(item.userid, StringComparison.OrdinalIgnoreCase)
                                                    )
                                        where oitem != null && nitem != null
                                        where !Compare<SmppSenderTempModel>(oitem, nitem)
                                        select nitem).ToList();

                    updateditems.AddRange(removedlist);
                    updateditems.AddRange(newlist);

                    updateditems = updateditems.GroupBy(g => g.userid).Select(s => s.First()).ToList();

                    // + "\"" + re.userid + "\"" +
                    // "+ "\"update\"" +"

                    var finalxml = updateditems.Aggregate(string.Empty,
                       (current, re) =>
                           current +
                           (@"<user id='" + "\"" + re.userid + "\"" + "' type=" + "\"dns\"" + "><action type=" + "\"update\"" + "></action></user>"));

                    // + "\"" + re.userid + "\"" +
                    // "+ "\"cache\"" +"

                    if (!string.IsNullOrWhiteSpace(finalxml.Trim()) && finalxml.Trim() != "")
                    {
                        using (var publisher = new TopicPublisher(session, TOPIC_NAME))
                        {
                            //publisher.SendMessage("Refresh app updated.");
                            publisher.SendMessage("<root id=" + "\"cache\"" + ">" + finalxml + "</root>");
                        }
                        //connection.Close();
                    }

                    // End code to be check
                }
                else
                {
                    var tempNewElements = CovertXmlToSmppSenderTempModel(xDoc);
                    tempNewElements = tempNewElements.GroupBy(g => g.userid).Select(s => s.First()).ToList();

                    // + "\"" + re.userid + "\"" +
                    // "+ "\"cache\"" +"

                    var finalxml = tempNewElements.Aggregate(string.Empty,
                       (current, re) =>
                           current +
                           (@"<user id=" + "\"" + re.userid + "\"" + " type=" + "\"dns\"" + "><action type=" + "\"update\"" + "></action></user>"));

                    if (!string.IsNullOrWhiteSpace(finalxml.Trim()) && finalxml.Trim() != "")
                    {
                        using (var publisher = new TopicPublisher(session, TOPIC_NAME))
                        {
                            //publisher.SendMessage("Refresh app updated.");
                            publisher.SendMessage("<root id=" + "\"cache\"" + ">" + finalxml + "</root>");
                        }
                        //connection.Close();
                    }

                }
            }
            catch (Exception exp)
            {
                var ex = exp.Message;
                Logger.Info(ex);
            }
        }

        private string ValidateOldElementsRoute(dynamic elements)
        {

            //<user id="2" type="route">
            //    <action type="update" />
            //</user>

            var esmeelement = string.Empty;
            try
            {
                foreach (var ele in elements)
                {
                    var oXDoc = XDocument.Parse(ele.o.ToString()) as XDocument;
                    var nXDoc = XDocument.Parse(ele.n.ToString()) as XDocument;

                    var fieldselement = string.Empty;

                    foreach (var ox in oXDoc.Root.Elements())
                    {
                        var ne = nXDoc.Root.Element(XName.Get(ox.Name.LocalName));
                        var oValue = ox.Value;
                        var neValue = ne.Value;
                        if (oValue.Contains(','))
                        {
                            var oArray = oValue.Split(',').ToList();
                            var nArray = neValue.Split(',').ToList();
                            bool isSubset = !oArray.Except(nArray).Any();
                            if (!isSubset)
                            {
                                fieldselement += ox.Name.LocalName + '|';
                            }
                        }
                        else
                        {
                            if (!oValue.Equals(neValue, StringComparison.OrdinalIgnoreCase))
                            {
                                fieldselement += ox.Name.LocalName + '|';
                            }
                        }
                    }
                    if (!string.IsNullOrWhiteSpace(fieldselement))
                    {
                        // + "\"" + oXDoc.Root.Elements(XName.Get("userid")).ToString().Trim() + "\"" +
                        // "+ "\"update\"" +"

                        if (fieldselement.EndsWith("|"))
                        {
                            fieldselement = fieldselement.Substring(0, fieldselement.Length - 1);
                            if (!string.IsNullOrWhiteSpace(fieldselement))
                            {
                                esmeelement += "<user id=" + "\"" + oXDoc.Root.Elements(XName.Get("userid")).ToString().Trim() + "\"" +
                                               " type=" + "\"route\"" + "><action type=" + "\"update\"" + "></action></userid>";
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                var err = ex.ToString();
                Logger.Info(err);
            }
            //return !string.IsNullOrWhiteSpace(esmeelement) ? ("<root id='" + keyName + "'>" + esmeelement + "</root>") : string.Empty;
            return esmeelement;
        }


