        private bool IsValidXml(string xmlText)
        {
            var isValid = false;
            try
            {
                XmlDocument xmlDoc = new XmlDocument();
                xmlDoc.LoadXml(xmlText);
                isValid = true;
            }
            catch (Exception ex)
            {
                Logger.Info(ex.Message);
            }
            return isValid;
        }

