        public async Task<DownloadDlrResponseMain> GetDownloadDlrWiseAsync(DownloadDlrRequest request)
        {
            Logger.InfoFormat("GetDownloadDlrWiseAsync :: Started :: {0}", request.UID);
            var OptWise = new DownloadDlrResponseMain
            {
                DownloadDlrResponse = new List<DownloadDlrResponse>(),
                DownloadResponsecount = new List<DownloadResponsecount>()
            };
            try
            {
                using (var dbConsumer = new CoreDBConsumer())
                {
                    var optdata =
                        await
                            dbConsumer.DbConsumerForMultiItems<DataTable>("GetClubAppOTPReport",
                                SqlEventTypes.Select,
                                new Dictionary<string, object>
                                {
                                    {"@strFromDate", request.FromDate},
                                    {"@strToDate", request.Todate},
                                    {"@UserId", Convert.ToInt32(request.UserName)},
                                    {"@Senderid", request.Sender},
                                    {"@Mobileno", request.MobileNo ?? ""},
                                    {"@UID",request.UID},
                                    {"@UserIp",request.UserIp},
                                    {"@isDownload", request.isDownload}
                                }, false, DBs.ReportsEngine);
                    Logger.InfoFormat("GetDownloadDlrWiseAsync :: Ended :: {0}", request.UID);
                    if (optdata != null && optdata.Any())
                    {
                        OptWise.DownloadDlrResponse = optdata[0].ToList<DownloadDlrResponse>();
                        //OptWise.DownloadDlrResponse = optdata.ToList<DownloadDlrResponse>();
                        OptWise.DownloadResponsecount = optdata[1].ToList<DownloadResponsecount>();
                    }
                    return OptWise;
                }
            }
            catch (Exception ex)
            {
                Logger.ErrorFormat("GetOPTWiseAsync Fatal Error :: {0}, UserId:- {1}", ex.ToString(), request.UID);
                ErrorSignal.FromCurrentContext().Raise(ex);
            }
            return OptWise;
        }
