        public async Task<OperatorResponse> GetDlrPercentageAsync(DLRPercentageSearch request)
        {
            Logger.Info("GetDlrPercentageAsync - start : " + DateTime.Now);

            try
            {
                using (var dbconsumer = new CoreDBConsumer())
                {
                    var tables = await dbconsumer.DbConsumerForMultiItems<DataTable>("GetOperatorWiseDLRPercentage_Sales",
                        SqlEventTypes.Select, new Dictionary<string, object> {
                                    {"@dtPickDLRPercentFrom", request.fromDate},
                                    {"@dtPickDLRPercentTo", request.toDate},
                                    {"@Sender",request.sender.Trim()}
                        }, false, DBs.ReportsEngine);
                    OperatorResponse OperatorResponse = new OperatorResponse();
